template <int Dim>
std::vector<double> AmrSystem<Dim>::level_state(int level) {
  return level_state_global(level);
}

template <int Dim>
std::vector<double> AmrSystem<Dim>::level_state_global(int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  const ExecutionLane& lane = p_->require_prepared_engine_lane("AMR level-state gather");
  const auto& hierarchy = p_->engine->hierarchy();
  std::string semantic_identity;
  std::exception_ptr local_error;
  try {
    if (level < 0 || static_cast<std::size_t>(level) >= hierarchy.num_levels())
      throw std::out_of_range("AmrSystem level is out of range");
    ExactContractBuilder exact;
    exact.text("pops.amr.level-state-gather").scalar(std::uint32_t{1}).scalar(std::int32_t{level});
    semantic_identity = std::move(exact).release();
  } catch (...) {
    local_error = std::current_exception();
  }
  runtime::system::auxiliary_ghost_detail::rethrow_collective_failure(
      local_error, &lane, "AMR level-state gather preflight failed collectively");
  return gather_field(hierarchy.state(static_cast<std::size_t>(level)),
                      hierarchy.layout(static_cast<std::size_t>(level)).domain(),
                      hierarchy.state(static_cast<std::size_t>(level)).ncomp(), semantic_identity,
                      lane);
}

template <int Dim>
void AmrSystem<Dim>::set_level_state(int level, const std::vector<double>& state) {
  p_->ensure_engine();
  if (level < 0 || static_cast<std::size_t>(level) >= p_->engine->hierarchy().num_levels())
    throw std::out_of_range("AmrSystem level is out of range");
  auto& hierarchy = p_->engine->hierarchy();
  write_field(hierarchy.state(static_cast<std::size_t>(level)),
              hierarchy.layout(static_cast<std::size_t>(level)).domain(), state,
              hierarchy.state(static_cast<std::size_t>(level)).ncomp());
  p_->discard_level_evaluations();
}

template <int Dim>
std::vector<double> AmrSystem<Dim>::block_level_state(const std::string& name, int level) {
  return block_level_state_global(name, level);
}

template <int Dim>
std::vector<double> AmrSystem<Dim>::block_level_state_global(const std::string& name, int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  const ExecutionLane& lane = p_->require_prepared_engine_lane("AMR block-level-state gather");
  std::size_t block_index = 0;
  std::string semantic_identity;
  std::exception_ptr local_error;
  try {
    block_index = p_->block_index(name);
    if (level < 0 || static_cast<std::size_t>(level) >= p_->engine->hierarchy().num_levels())
      throw std::out_of_range("AmrSystem block level is out of range");
    ExactContractBuilder exact;
    exact.text("pops.amr.block-level-state-gather")
        .scalar(std::uint32_t{1})
        .text(name)
        .scalar(static_cast<std::uint64_t>(block_index))
        .scalar(std::int32_t{level});
    semantic_identity = std::move(exact).release();
  } catch (...) {
    local_error = std::current_exception();
  }
  runtime::system::auxiliary_ghost_detail::rethrow_collective_failure(
      local_error, &lane, "AMR block-level-state gather preflight failed collectively");
  const std::size_t index = static_cast<std::size_t>(level);
  const MultiFab<Dim>& state = p_->block_state(block_index, index);
  return gather_field(state, p_->engine->hierarchy().layout(index).domain(), state.ncomp(),
                      semantic_identity, lane);
}

template <int Dim>
void AmrSystem<Dim>::set_block_level_state(const std::string& name, int level,
                                           const std::vector<double>& state) {
  const std::size_t block_index = p_->block_index(name);
  p_->ensure_engine();
  if (level < 0 || static_cast<std::size_t>(level) >= p_->engine->hierarchy().num_levels())
    throw std::out_of_range("AmrSystem block level is out of range");
  const std::size_t index = static_cast<std::size_t>(level);
  MultiFab<Dim>& target = p_->block_state(block_index, index);
  write_field(target, p_->engine->hierarchy().layout(index).domain(), state, target.ncomp());
  p_->discard_level_evaluations();
}

template <int Dim>
std::vector<OutputPiece<Dim>> AmrSystem<Dim>::output_state_local_pieces(const std::string& name,
                                                                        int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  const std::size_t block_index = p_->block_index(name);
  p_->ensure_engine();
  if (level < 0 || static_cast<std::size_t>(level) >= p_->engine->hierarchy().num_levels())
    throw std::out_of_range("AmrSystem output level is out of range");
  const MultiFab<Dim>& state = p_->block_state(block_index, static_cast<std::size_t>(level));
  return output_local_pieces(state, level, state.distribution().replicated());
}

template <int Dim>
std::vector<OutputPiece<Dim>> AmrSystem<Dim>::output_embedded_boundary_local_pieces(
    const std::string& name, int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  if (level < 0 ||
      static_cast<std::size_t>(level) >= p_->prepared_hierarchy->embedded_boundary.size())
    throw std::out_of_range("AmrSystem embedded-boundary output level is out of range");
  const auto& embedded = p_->prepared_hierarchy->embedded_boundary[static_cast<std::size_t>(level)];
  if (!embedded)
    throw std::logic_error("AmrSystem has no prepared embedded-boundary geometry");
  const MultiFab<Dim>* field = nullptr;
  if (name == "pops_active")
    field = &embedded->active_mask();
  else if (name == "pops_phi")
    field = &embedded->phi();
  else if (name == "pops_kappa")
    field = &embedded->volume_fraction();
  else
    throw std::invalid_argument("unknown AMR embedded-boundary sidecar: " + name);
  return output_local_pieces(*field, level, field->distribution().replicated());
}

template <int Dim>
std::vector<OutputPiece<Dim>> AmrSystem<Dim>::output_state_root_pieces(const ObserverMpiLane& lane,
                                                                       const std::string& name,
                                                                       int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->require_no_native_package_callback("output_state_root_pieces");
  return output_pieces_to_root(
      lane, detail::output_collective_identity("amr_system", "state", name, level),
      [&] { return output_state_local_pieces(name, level); });
}

template <int Dim>
std::vector<OutputPiece<Dim>> AmrSystem<Dim>::output_embedded_boundary_root_pieces(
    const ObserverMpiLane& lane, const std::string& name, int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->require_no_native_package_callback("output_embedded_boundary_root_pieces");
  if (lane.size() == 1)
    return output_embedded_boundary_local_pieces(name, level);
  return output_pieces_to_root(
      lane, detail::output_collective_identity("amr_system", "embedded-boundary", name, level),
      [&] { return output_embedded_boundary_local_pieces(name, level); });
}

template <int Dim>
double AmrSystem<Dim>::composite_reduce(const std::string& name, const std::string& kind,
                                        int component,
                                        const std::vector<int>& requested_levels) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  const std::size_t block_index = p_->block_index(name);
  const typename Impl::BlockSpec& block = p_->blocks[block_index];
  p_->ensure_engine();
  if (kind == "sum_all" || kind == "abs_sum_all" || kind == "sum_sq_all" || kind == "abs_max_all") {
    const std::string base = kind == "sum_all"       ? "sum"
                             : kind == "abs_sum_all" ? "abs_sum"
                             : kind == "sum_sq_all"  ? "sum_sq"
                                                     : "abs_max";
    double result = 0.0;
    for (int current = 0; current < block.ncomp; ++current) {
      const double value = composite_reduce(name, base, current, requested_levels);
      result = kind == "abs_max_all" ? std::max(result, value) : result + value;
    }
    return result;
  }
  if (component < 0 || component >= block.ncomp)
    throw std::out_of_range("AMR composite reduction component is outside the block state");
  const auto levels =
      resolved_composite_levels(p_->engine->hierarchy().num_levels(), requested_levels);
  std::vector<std::shared_ptr<const MultiFab<Dim>>> selected_coverage;
  const std::vector<std::shared_ptr<const MultiFab<Dim>>>* coverage =
      &p_->prepared_hierarchy->active_coverage;
  if (!requested_levels.empty()) {
    selected_coverage = Impl::prepare_active_coverage(*p_->engine, levels);
    coverage = &selected_coverage;
  }
  std::vector<runtime::amr::CompositeLevelView<Dim, memory_space>> views;
  views.reserve(levels.size());
  for (std::size_t position = 0; position < levels.size(); ++position) {
    const int level = levels[position];
    const std::size_t index = static_cast<std::size_t>(level);
    const Box<Dim>& domain = p_->engine->hierarchy().layout(index).domain();
    const Geometry<Dim> geometry = Geometry<Dim>::from_bounds(domain, p_->cfg.lower, p_->cfg.upper);
    std::array<Real, Dim> extent{};
    for (int axis = 0; axis < Dim; ++axis)
      extent[static_cast<std::size_t>(axis)] = geometry.spacing(axis);
    const MultiFab<Dim>* relative = nullptr;
    const auto& embedded = p_->prepared_hierarchy->embedded_boundary[index];
    if (embedded && embedded->mode() == runtime::system::PreparedEmbeddedBoundaryMode::staircase)
      relative = &embedded->active_mask();
    else if (embedded &&
             embedded->mode() == runtime::system::PreparedEmbeddedBoundaryMode::cut_cell)
      relative = &embedded->volume_fraction();
    const std::size_t coverage_index = requested_levels.empty() ? index : position;
    views.push_back({&p_->block_state(block_index, index), (*coverage)[coverage_index].get(),
                     extent, relative});
  }
  return static_cast<double>(
      runtime::amr::composite_reduce<Dim, memory_space>(
          views, component, composite_reduction_kind(kind), *p_->prepared_hierarchy->lane)
          .value);
}

template <int Dim>
double AmrSystem<Dim>::composite_reduce_field(const std::string& provider_slot,
                                              const std::string& kind, int component,
                                              const std::vector<int>& requested_levels) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  const std::string slot = p_->resolve_field_slot(provider_slot);
  p_->materialize_field(slot);
  const typename Impl::FieldPlan& plan = p_->field_plans.at(slot);
  const auto levels = resolved_composite_levels(plan.accepted_potential.size(), requested_levels);
  std::vector<std::shared_ptr<const MultiFab<Dim>>> selected_coverage;
  const std::vector<std::shared_ptr<const MultiFab<Dim>>>* coverage = &plan.active_coverage;
  if (!requested_levels.empty()) {
    selected_coverage = Impl::prepare_active_coverage(*p_->engine, levels);
    coverage = &selected_coverage;
  }
  const int ncomp = plan.accepted_potential.empty() ? 0 : plan.accepted_potential.front()->ncomp();
  if (component < 0 || component >= ncomp)
    throw std::out_of_range("AMR composite field component is outside the prepared field");
  if (kind == "sum_all" || kind == "abs_sum_all" || kind == "sum_sq_all" || kind == "abs_max_all") {
    const std::string base = kind == "sum_all"       ? "sum"
                             : kind == "abs_sum_all" ? "abs_sum"
                             : kind == "sum_sq_all"  ? "sum_sq"
                                                     : "abs_max";
    double result = 0.0;
    for (int current = 0; current < ncomp; ++current) {
      const double value = composite_reduce_field(slot, base, current, requested_levels);
      result = kind == "abs_max_all" ? std::max(result, value) : result + value;
    }
    return result;
  }
  std::vector<runtime::amr::CompositeLevelView<Dim, memory_space>> views;
  views.reserve(levels.size());
  for (std::size_t position = 0; position < levels.size(); ++position) {
    const int level = levels[position];
    const std::size_t index = static_cast<std::size_t>(level);
    const Box<Dim>& domain = p_->engine->hierarchy().layout(index).domain();
    const Geometry<Dim> geometry = Geometry<Dim>::from_bounds(domain, p_->cfg.lower, p_->cfg.upper);
    std::array<Real, Dim> extent{};
    for (int axis = 0; axis < Dim; ++axis)
      extent[static_cast<std::size_t>(axis)] = geometry.spacing(axis);
    const std::size_t coverage_index = requested_levels.empty() ? index : position;
    views.push_back(
        {plan.accepted_potential[index].get(), (*coverage)[coverage_index].get(), extent, nullptr});
  }
  return static_cast<double>(
      runtime::amr::composite_reduce<Dim, memory_space>(
          views, component, composite_reduction_kind(kind), *p_->prepared_hierarchy->lane)
          .value);
}

template <int Dim>
void AmrSystem<Dim>::set_hierarchy(const std::vector<AmrPatch<Dim>>& boxes) {
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AmrSystem::set_hierarchy requires its prepared hierarchy lane");
  if (p_->prepared_hierarchy->lane->size() != 1)
    throw std::runtime_error(
        "AmrSystem::set_hierarchy under MPI requires rebuild_hierarchy with explicit owner ranks");
  rebuild_hierarchy(boxes, std::vector<int>(boxes.size(), 0));
}

template <int Dim>
void AmrSystem<Dim>::rebuild_hierarchy(const std::vector<AmrPatch<Dim>>& boxes,
                                       const std::vector<int>& owner_ranks) {
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AMR hierarchy rebuild requires its prepared hierarchy lane");
  const ExecutionLane& lane = *p_->prepared_hierarchy->lane;
  // The carrier contract is rooted in the durable package lane.  A rebuild may use the prepared
  // lane for its outer collective validation, but recreating the carrier beneath that already
  // duplicated lane would change the exact lane identity and make an otherwise authentic
  // accepted snapshot impossible to restore.  Reuse the bootstrap root and component identity.
  const ExecutionLane& package_lane = p_->require_package_assembly_lane();
  std::vector<std::vector<Box<Dim>>> level_boxes;
  std::vector<std::vector<int>> level_owners;
  std::string request_contract;
  std::exception_ptr validation_error;
  try {
    if (boxes.size() != owner_ranks.size())
      throw std::invalid_argument(
          "AmrSystem::rebuild_hierarchy boxes and owner ranks must align exactly");
    int active_levels = 1;
    std::vector<int> level_mode;
    for (std::size_t index = 0; index < boxes.size(); ++index) {
      const AmrPatch<Dim>& patch = boxes[index];
      if (patch.level < 1 || patch.level >= p_->cfg.level_count || patch.box.empty())
        throw std::invalid_argument(
            "AmrSystem::rebuild_hierarchy requires non-empty configured fine-level patches");
      if (owner_ranks[index] < -1 || owner_ranks[index] >= lane.size())
        throw std::out_of_range(
            "AmrSystem::rebuild_hierarchy owner rank lies outside the execution lane");
      const std::size_t level = static_cast<std::size_t>(patch.level);
      if (level_mode.size() <= level)
        level_mode.resize(level + 1, -2);
      const int mode = owner_ranks[index] == -1 ? -1 : 0;
      if (level_mode[level] != -2 && level_mode[level] != mode)
        throw std::invalid_argument(
            "AmrSystem::rebuild_hierarchy forbids mixed replicated and partitioned owner rows");
      level_mode[level] = mode;
      active_levels = std::max(active_levels, patch.level + 1);
    }
    level_boxes.resize(static_cast<std::size_t>(active_levels));
    level_owners.resize(static_cast<std::size_t>(active_levels));
    ExactContractBuilder request;
    request.text("pops.amr-system.rebuild-hierarchy")
        .scalar(std::uint32_t{2})
        .scalar(std::int32_t{Dim})
        .scalar(static_cast<std::uint64_t>(boxes.size()));
    for (std::size_t index = 0; index < boxes.size(); ++index) {
      const AmrPatch<Dim>& patch = boxes[index];
      const std::size_t level = static_cast<std::size_t>(patch.level);
      level_boxes[level].push_back(patch.box);
      level_owners[level].push_back(owner_ranks[index]);
      request.scalar(std::int32_t{patch.level});
      for (int axis = 0; axis < Dim; ++axis)
        request.scalar(std::int32_t{patch.box.lo[axis]});
      for (int axis = 0; axis < Dim; ++axis)
        request.scalar(std::int32_t{patch.box.hi[axis]});
      request.scalar(std::int32_t{owner_ranks[index]});
    }
    for (int level = 1; level < active_levels; ++level)
      if (level_boxes[static_cast<std::size_t>(level)].empty())
        throw std::invalid_argument(
            "AmrSystem::rebuild_hierarchy requires contiguous active fine levels");
    request_contract = std::move(request).release();
  } catch (...) {
    validation_error = std::current_exception();
  }
  if (all_reduce_max(validation_error ? 1L : 0L, lane) != 0) {
    if (lane.size() == 1 && validation_error)
      std::rethrow_exception(validation_error);
    throw std::runtime_error("AMR hierarchy rebuild validation failed collectively");
  }
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-rebuild-hierarchy"), std::string_view(request_contract)}}, lane))
    throw std::invalid_argument("AMR hierarchy rebuild request differs between MPI ranks");

  p_->execute_step_transaction([&] {
    using engine_type = typename Impl::engine_type;
    using hierarchy_type = typename engine_type::hierarchy_type;
    using level_type = typename engine_type::level_type;
    using field_type = typename engine_type::field_type;

    const auto& live_hierarchy = p_->engine->hierarchy();
    hierarchy_type candidate_hierarchy = live_hierarchy.truncated(0);
    const mesh::RankSpace<Dim>& rank_space = live_hierarchy.layout(0).distribution().rank_space();
    const Index<Dim> local_rank = live_hierarchy.state(0).local_rank();
    Box<Dim> level_domain = live_hierarchy.layout(0).domain();
    for (std::size_t level = 1; level < level_boxes.size(); ++level) {
      const auto ratio = refinement_ratio(p_->cfg.transition_ratios[level - 1]);
      level_domain = amr::hierarchy::refine_box(level_domain, ratio);
      mesh::BoxArray<Dim> patches(level_boxes[level]);
      std::vector<Index<Dim>> owners;
      const bool replicated = level_owners[level].front() == -1;
      if (!replicated) {
        owners.reserve(level_owners[level].size());
        for (int rank : level_owners[level])
          owners.push_back(rank_space.coordinate(static_cast<std::size_t>(rank)));
      }
      mesh::Distribution<Dim> distribution =
          replicated ? mesh::Distribution<Dim>::replicated(patches, rank_space)
                     : mesh::Distribution<Dim>::partitioned(patches, rank_space, std::move(owners));
      const mesh::BoxArrayValidationBudget layout_budget{patches.size(),
                                                         checked_pair_count(patches.size())};
      amr::hierarchy::LevelLayout<Dim> layout(static_cast<int>(level), level_domain, patches,
                                              distribution, ratio, layout_budget);
      field_type state(patches, distribution, local_rank, live_hierarchy.state(0).ncomp(),
                       live_hierarchy.state(0).ghosts());
      state.set_val(Real(0));
      candidate_hierarchy =
          candidate_hierarchy.with_level(level_type(std::move(layout), std::move(state)));
    }

    auto candidate_engine = std::make_shared<engine_type>(
        std::move(candidate_hierarchy), p_->load_balance, p_->engine->spatial_identity());
    auto qualified = candidate_engine->snapshot();
    qualified.topology_epoch = runtime::amr::detail::next_generation(
        p_->engine->topology_epoch(), "AMR hierarchy topology epoch");
    qualified.materialization_generation = runtime::amr::detail::next_generation(
        p_->engine->materialization_generation(), "AMR hierarchy materialization generation");
    qualified.exact_spatial_contract = runtime::amr::detail::exact_runtime_spatial_contract(
        candidate_engine->spatial_identity(), qualified.hierarchy, qualified.topology_epoch,
        qualified.materialization_generation);
    candidate_engine->restore(qualified);
    std::vector<typename Impl::multiblock_type::AdditionalBlock> additional;
    additional.reserve(p_->blocks.size() - 1);
    for (std::size_t block = 1; block < p_->blocks.size(); ++block) {
      std::vector<field_type> levels;
      levels.reserve(candidate_engine->hierarchy().num_levels());
      for (std::size_t level = 0; level < candidate_engine->hierarchy().num_levels(); ++level) {
        const field_type& primary = candidate_engine->hierarchy().state(level);
        levels.emplace_back(primary.layout(), primary.distribution(), primary.local_rank(),
                            p_->blocks[block].ncomp, p_->blocks[block].ghosts);
        levels.back().set_val(Real(0));
      }
      additional.push_back({p_->blocks[block].name, std::move(levels)});
    }
    std::optional<runtime::program::HistoryManager<Dim>> provisional_histories;
    std::exception_ptr provisional_history_error;
    try {
      const auto& source = p_->program.hist_;
      if (!source.histories.empty()) {
        struct Descriptor {
          int owner = -1;
          int depth = 0;
          int components = 0;
          std::string state;
          std::string space;
          std::string clock;
          std::string interpolation;

          bool operator==(const Descriptor&) const = default;
        };
        std::map<std::string, Descriptor> descriptors;
        std::map<std::string, std::set<int>> levels_by_name;
        const std::size_t source_levels = live_hierarchy.num_levels();
        for (const auto& [key, ring] : source.histories) {
          const auto decoded = decode_exact_amr_history_key(key);
          if (!decoded || decoded->first < 0 ||
              static_cast<std::size_t>(decoded->first) >= source_levels ||
              key != exact_amr_history_key(decoded->second, decoded->first))
            throw std::invalid_argument(
                "AMR restart hierarchy rebuild has a malformed provisional history key");
          const int depth = source.depth.at(key);
          const int owner = source.owner.at(key);
          const bool initialized = source.initialized.at(key);
          const int fill_count = source.fill_count.at(key);
          const bool pending = source.store_pending.at(key);
          const auto& dts = source.slot_dt.at(key);
          if (depth < 1 || ring.size() != static_cast<std::size_t>(depth) ||
              dts.size() != ring.size() || initialized || fill_count != 0 || pending ||
              !std::all_of(
                  dts.begin(), dts.end(), [](Real dt) { return dt == Real(0); }) ||
              owner < 0 || static_cast<std::size_t>(owner) >= p_->blocks.size() ||
              source.state_identity.at(key).empty() || source.space_identity.at(key).empty() ||
              source.clock_identity.at(key).empty() ||
              source.interpolation_identity.at(key).empty() || ring.empty() ||
              ring.front().ncomp() < 1)
            throw std::runtime_error(
                "AMR restart hierarchy rebuild cannot rematerialize retained history provenance");
          for (const field_type& slot : ring)
            if (slot.ncomp() != ring.front().ncomp())
              throw std::runtime_error(
                  "AMR restart hierarchy rebuild has inconsistent provisional history components");
          const Descriptor descriptor{owner,
                                      depth,
                                      ring.front().ncomp(),
                                      source.state_identity.at(key),
                                      source.space_identity.at(key),
                                      source.clock_identity.at(key),
                                      source.interpolation_identity.at(key)};
          auto [found, inserted] = descriptors.emplace(decoded->second, descriptor);
          if (!inserted && found->second != descriptor)
            throw std::runtime_error(
                "AMR restart hierarchy rebuild has mixed provisional history descriptors");
          if (!levels_by_name[decoded->second].insert(decoded->first).second)
            throw std::runtime_error(
                "AMR restart hierarchy rebuild has duplicate provisional history levels");
        }
        for (const auto& [name, descriptor] : descriptors) {
          const auto levels = levels_by_name.find(name);
          if (levels == levels_by_name.end() || levels->second.size() != source_levels)
            throw std::runtime_error(
                "AMR restart hierarchy rebuild has incomplete provisional history levels");
          for (std::size_t level = 0; level < source_levels; ++level)
            if (!levels->second.contains(static_cast<int>(level)))
              throw std::runtime_error(
                  "AMR restart hierarchy rebuild has incomplete provisional history levels");
          (void)descriptor;
        }
        provisional_histories.emplace();
        for (const auto& [name, descriptor] : descriptors) {
          for (std::size_t level = 0; level < candidate_engine->hierarchy().num_levels(); ++level) {
            const std::string key = exact_amr_history_key(name, static_cast<int>(level));
            const field_type* prototype = nullptr;
            if (descriptor.owner == 0) {
              prototype = &candidate_engine->hierarchy().state(level);
            } else {
              const std::size_t additional_index = static_cast<std::size_t>(descriptor.owner - 1);
              if (additional_index >= additional.size() ||
                  level >= additional[additional_index].levels.size())
                throw std::runtime_error(
                    "AMR restart hierarchy rebuild has no authenticated owner carrier");
              prototype = &additional[additional_index].levels[level];
            }
            std::vector<field_type> ring;
            ring.reserve(static_cast<std::size_t>(descriptor.depth));
            for (int slot = 0; slot < descriptor.depth; ++slot) {
              field_type empty(prototype->layout(), prototype->distribution(),
                               prototype->local_rank(), descriptor.components, prototype->ghosts());
              empty.set_val(Real(0));
              ring.push_back(std::move(empty));
            }
            provisional_histories->histories.emplace(key, std::move(ring));
            provisional_histories->depth.emplace(key, descriptor.depth);
            provisional_histories->initialized.emplace(key, false);
            provisional_histories->fill_count.emplace(key, 0);
            provisional_histories->store_pending.emplace(key, false);
            provisional_histories->owner.emplace(key, descriptor.owner);
            provisional_histories->state_identity.emplace(key, descriptor.state);
            provisional_histories->space_identity.emplace(key, descriptor.space);
            provisional_histories->clock_identity.emplace(key, descriptor.clock);
            provisional_histories->interpolation_identity.emplace(key, descriptor.interpolation);
            provisional_histories->slot_dt.emplace(
                key, std::vector<Real>(static_cast<std::size_t>(descriptor.depth), Real(0)));
          }
        }
      }
    } catch (...) {
      provisional_history_error = std::current_exception();
    }
    if (all_reduce_max(provisional_history_error ? 1L : 0L, lane) != 0) {
      if (lane.size() == 1 && provisional_history_error)
        std::rethrow_exception(provisional_history_error);
      throw std::runtime_error(
          "AMR restart hierarchy provisional histories failed validation collectively");
    }
    std::optional<typename Impl::multiblock_type> multiblock_staged;
    std::exception_ptr carrier_preparation_error;
    try {
      multiblock_staged.emplace(Impl::multiblock_type::prepare_collectively(
          package_lane, candidate_engine, p_->blocks.front().name, std::move(additional),
          "pops.amr-system.multiblock"));
    } catch (...) {
      carrier_preparation_error = std::current_exception();
    }
    if (all_reduce_max(carrier_preparation_error ? 1L : 0L, lane) != 0) {
      if (lane.size() == 1 && carrier_preparation_error)
        std::rethrow_exception(carrier_preparation_error);
      throw std::runtime_error("AMR hierarchy rebuild carrier preparation failed collectively");
    }
    for (const auto& coupling : p_->prepared_couplings)
      multiblock_staged->install_prepared_coupling_operator(coupling.provider_contract,
                                                            coupling.view, coupling.operation);
    multiblock_staged->seal_couplings();
    std::unique_ptr<typename Impl::multiblock_type> candidate_multiblock;
    std::exception_ptr carrier_allocation_error;
    try {
      candidate_multiblock =
          std::make_unique<typename Impl::multiblock_type>(std::move(*multiblock_staged));
    } catch (...) {
      carrier_allocation_error = std::current_exception();
    }
    if (all_reduce_max(carrier_allocation_error ? 1L : 0L, lane) != 0) {
      static_assert(std::is_nothrow_move_assignable_v<typename Impl::multiblock_type>);
      if (candidate_multiblock)
        *multiblock_staged = std::move(*candidate_multiblock);
      if (lane.size() == 1 && carrier_allocation_error)
        std::rethrow_exception(carrier_allocation_error);
      throw std::runtime_error("AMR hierarchy rebuild carrier allocation failed collectively");
    }
    // Convert the completely qualified carrier into the generic staged successor.  It performs
    // no accepted write here: forward graph/map/flux/Program images and the inverse are all
    // prepared while the transaction still owns Candidate, then the existing no-throw
    // HiddenPublish/finalizer pair consumes that one authority.
    auto replacement = p_->multiblock_hierarchy->prepare_full_rebuild_transaction(
        candidate_multiblock->snapshot());
    p_->step_transaction_carrier.stage_full_rebuild_transaction(std::move(replacement),
                                                                std::move(provisional_histories));
  });
}

template <int Dim>
std::vector<int> AmrSystem<Dim>::rematerialize_hierarchy_ownership(
    const std::vector<AmrPatch<Dim>>& boxes, const std::vector<std::string>& level_modes) {
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AMR ownership rematerialization requires its prepared hierarchy lane");
  const ExecutionLane& lane = *p_->prepared_hierarchy->lane;
  std::vector<std::vector<Box<Dim>>> level_boxes;
  std::vector<std::vector<std::size_t>> source_indices;
  std::string request_contract;
  std::exception_ptr validation_error;
  try {
    int active_levels = 1;
    for (const AmrPatch<Dim>& patch : boxes) {
      if (patch.level < 1 || patch.level >= p_->cfg.level_count || patch.box.empty())
        throw std::invalid_argument(
            "AMR ownership rematerialization requires non-empty configured fine-level patches");
      active_levels = std::max(active_levels, patch.level + 1);
    }
    if (level_modes.size() != static_cast<std::size_t>(active_levels))
      throw std::invalid_argument(
          "AMR ownership rematerialization modes must cover every active level");
    for (const auto& mode : level_modes)
      if (mode != "replicated" && mode != "partitioned")
        throw std::invalid_argument(
            "AMR ownership rematerialization has an unknown distribution mode");
    level_boxes.resize(static_cast<std::size_t>(active_levels));
    source_indices.resize(static_cast<std::size_t>(active_levels));
    ExactContractBuilder request;
    request.text("pops.amr-system.rematerialize-ownership")
        .scalar(std::uint32_t{2})
        .scalar(std::int32_t{Dim})
        .scalar(static_cast<std::uint64_t>(boxes.size()));
    for (std::size_t index = 0; index < boxes.size(); ++index) {
      const AmrPatch<Dim>& patch = boxes[index];
      const std::size_t level = static_cast<std::size_t>(patch.level);
      level_boxes[level].push_back(patch.box);
      source_indices[level].push_back(index);
      request.scalar(std::int32_t{patch.level});
      for (int axis = 0; axis < Dim; ++axis)
        request.scalar(std::int32_t{patch.box.lo[axis]});
      for (int axis = 0; axis < Dim; ++axis)
        request.scalar(std::int32_t{patch.box.hi[axis]});
    }
    for (int level = 1; level < active_levels; ++level)
      if (level_boxes[static_cast<std::size_t>(level)].empty())
        throw std::invalid_argument(
            "AMR ownership rematerialization requires contiguous active fine levels");
    for (const auto& mode : level_modes)
      request.text(mode);
    request_contract = std::move(request).release();
  } catch (...) {
    validation_error = std::current_exception();
  }
  if (all_reduce_max(validation_error ? 1L : 0L, lane) != 0) {
    if (lane.size() == 1 && validation_error)
      std::rethrow_exception(validation_error);
    throw std::runtime_error("AMR ownership rematerialization validation failed collectively");
  }
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-rematerialize-ownership"), std::string_view(request_contract)}},
          lane))
    throw std::invalid_argument("AMR ownership rematerialization request differs between ranks");
  if (boxes.empty())
    return {};

  const mesh::RankSpace<Dim> rank_space = process_rank_space<Dim>(lane);
  std::vector<int> result(boxes.size(), -1);
  for (std::size_t level = 1; level < level_boxes.size(); ++level) {
    if (level_modes[level] == "replicated")
      continue;
    const mesh::BoxArray<Dim> patches(level_boxes[level]);
    const parallel::LoadBalancePreparationBudget budget{patches.size(), rank_space.size(),
                                                        checked_layout_cells(patches)};
    const auto prepared = p_->load_balance->prepare(patches, rank_space, budget, {}, lane);
    const auto& distribution = prepared.plan().distribution();
    for (std::size_t patch = 0; patch < patches.size(); ++patch)
      result[source_indices[level][patch]] =
          static_cast<int>(rank_space.linear_rank(distribution.owner(patch)));
  }
  return result;
}

template <int Dim>
std::vector<std::uint8_t> AmrSystem<Dim>::program_accepted_state_source_authority(
    const std::vector<std::vector<int>>& source_level_owners,
    const std::vector<std::string>& source_level_modes, int source_rank_count) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AMR Program source authority requires its prepared hierarchy lane");
  const ExecutionLane& lane = *p_->prepared_hierarchy->lane;
  std::string authority;
  std::exception_ptr local_error;
  try {
    if (source_rank_count != lane.size())
      throw std::invalid_argument(
          "AMR Program source authority rank count differs from its live prepared lane");
    const auto& hierarchy = p_->engine->hierarchy();
    if (source_level_owners.size() != hierarchy.num_levels() ||
        source_level_modes.size() != hierarchy.num_levels())
      throw std::invalid_argument(
          "AMR Program source authority topology must cover every active level");
    for (std::size_t level = 0; level < source_level_owners.size(); ++level) {
      const auto& distribution = hierarchy.layout(level).distribution();
      const std::string expected_mode = distribution.replicated() ? "replicated" : "partitioned";
      if (source_level_modes[level] != expected_mode ||
          source_level_owners[level].size() !=
              (distribution.replicated() ? 0 : distribution.owners().size()))
        throw std::invalid_argument(
            "AMR Program source authority topology differs from the live exact hierarchy");
      for (std::size_t patch = 0; patch < source_level_owners[level].size(); ++patch)
        if (source_level_owners[level][patch] !=
            static_cast<int>(distribution.rank_space().linear_rank(distribution.owner(patch))))
          throw std::invalid_argument(
              "AMR Program source authority owner map differs from the live exact hierarchy");
    }
    const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
    const std::vector<std::uint8_t> bytes = program_accepted_state();
    p_->require_program_checkpoint_capacity(bytes.size(),
                                            "AMR Program source-authority preparation");
    if (bytes.empty())
      throw std::logic_error("AMR Program source authority has no live accepted image");
    const auto state =
        runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
    runtime::program::require_live_amr_program_checkpoint(state, *p_->engine);
    p_->require_accepted_state_authority_contracts(state);
    authority = p_->source_accepted_state_authority_contract(state, source_level_owners,
                                                             source_level_modes, source_rank_count);
  } catch (...) {
    local_error = std::current_exception();
  }
  if (all_reduce_max(local_error ? 1L : 0L, lane) != 0) {
    if (lane.size() == 1 && local_error)
      std::rethrow_exception(local_error);
    throw std::runtime_error("AMR Program source authority preparation failed collectively");
  }
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-program-accepted-source-authority"), authority}}, lane))
    throw std::invalid_argument("AMR Program source authority differs between ranks");
  return {authority.begin(), authority.end()};
}

template <int Dim>
std::vector<std::uint8_t> AmrSystem<Dim>::rematerialize_program_accepted_state(
    const std::vector<std::uint8_t>& source_state, int source_rank_count,
    const std::vector<std::vector<int>>& source_level_owners,
    const std::vector<std::vector<int>>& target_level_owners,
    const std::vector<std::string>& source_level_modes,
    const std::vector<std::string>& target_level_modes,
    const std::vector<std::uint8_t>& source_authority) {
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AMR Program rematerialization requires its prepared hierarchy lane");
  const ExecutionLane& lane = *p_->prepared_hierarchy->lane;
  std::optional<runtime::program::AmrProgramAcceptedState<Dim>> accepted;
  std::string request_contract;
  std::exception_ptr validation_error;
  try {
    const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
    if (source_state.empty() || source_rank_count < 1)
      throw std::invalid_argument(
          "AMR Program rematerialization requires one canonical source image and rank count");
    p_->require_program_checkpoint_capacity(source_state.size(),
                                            "AMR Program rematerialization source");
    p_->require_program_source_authority_capacity(source_authority.size(),
                                                  "AMR Program rematerialization source authority");
    const std::size_t levels = p_->engine->hierarchy().num_levels();
    if (source_level_owners.size() != levels || target_level_owners.size() != levels ||
        source_level_modes.size() != levels || target_level_modes.size() != levels)
      throw std::invalid_argument(
          "AMR Program rematerialization topology must cover every active level");
    for (std::size_t level = 0; level < levels; ++level) {
      if ((source_level_modes[level] != "replicated" &&
           source_level_modes[level] != "partitioned") ||
          (target_level_modes[level] != "replicated" && target_level_modes[level] != "partitioned"))
        throw std::invalid_argument(
            "AMR Program rematerialization has an unknown distribution mode");
      if (source_level_modes[level] != target_level_modes[level])
        throw std::invalid_argument(
            "AMR Program rematerialization cannot change an exact distribution mode");
      if (source_level_owners[level].size() != target_level_owners[level].size())
        throw std::invalid_argument(
            "AMR Program source and target ownership name different patch counts");
      const auto& live = p_->engine->hierarchy().layout(level).distribution();
      const std::string live_mode = live.replicated() ? "replicated" : "partitioned";
      if (target_level_modes[level] != live_mode)
        throw std::invalid_argument(
            "AMR Program target distribution mode differs from the published hierarchy");
      const std::size_t live_owners = live.replicated() ? 0 : live.owners().size();
      if (target_level_owners[level].size() != live_owners)
        throw std::invalid_argument(
            "AMR Program target ownership differs from the live exact hierarchy");
      for (int owner : source_level_owners[level])
        if (owner < 0 || owner >= source_rank_count)
          throw std::out_of_range("AMR Program source owner rank is out of range");
      for (std::size_t patch = 0; patch < target_level_owners[level].size(); ++patch) {
        const int owner = target_level_owners[level][patch];
        if (owner < 0 || owner >= lane.size() ||
            owner != static_cast<int>(live.rank_space().linear_rank(live.owner(patch))))
          throw std::invalid_argument(
              "AMR Program target ownership differs from the published hierarchy");
      }
    }

    if (source_authority.empty())
      throw std::invalid_argument(
          "AMR Program rematerialization requires a sealed source authority");
    accepted.emplace(runtime::program::deserialize_amr_program_accepted_state<Dim>(
        source_state, &interface_budget));
    const std::string expected_source_authority = p_->source_accepted_state_authority_contract(
        *accepted, source_level_owners, source_level_modes, source_rank_count);
    const std::string_view provided_source_authority(
        reinterpret_cast<const char*>(source_authority.data()), source_authority.size());
    if (provided_source_authority != expected_source_authority)
      throw std::invalid_argument(
          "AMR Program rematerialization source differs from its sealed accepted authority");
    if (accepted->level_clocks.size() != levels)
      throw std::invalid_argument(
          "AMR Program accepted clocks differ from the rematerialized hierarchy depth");
    accepted->spatial_contract = p_->engine->spatial_contract();
    accepted->topology_epoch = p_->engine->topology_epoch();
    accepted->materialization_generation = p_->engine->materialization_generation();
    if (accepted->temporal_partition.kind == runtime::program::TemporalPartitionKind::CellLocal)
      accepted->temporal_partition.topology_epoch = accepted->topology_epoch;
    for (auto& fragment : accepted->accepted_interface_flux)
      fragment.key.topology_epoch = accepted->topology_epoch;
    auto contracts = p_->accepted_state_authority_contracts();
    accepted->flux_budget_contract = std::move(contracts.first);
    accepted->coupling_contract = std::move(contracts.second);
    p_->require_accepted_state_authority_contracts(*accepted);
    const std::vector<std::uint8_t> bytes =
        runtime::program::serialize_amr_program_accepted_state(*accepted);
    p_->require_program_checkpoint_capacity(bytes.size(), "AMR Program rematerialization result");
    ExactContractBuilder request;
    request.text("pops.amr-system.rematerialize-program-state")
        .scalar(std::uint32_t{2})
        .scalar(std::int32_t{Dim})
        .scalar(static_cast<std::uint64_t>(source_rank_count))
        .scalar(static_cast<std::uint64_t>(levels))
        .bytes(std::string_view(reinterpret_cast<const char*>(source_authority.data()),
                                source_authority.size()))
        .bytes(std::string_view(reinterpret_cast<const char*>(bytes.data()), bytes.size()));
    for (std::size_t level = 0; level < source_level_owners.size(); ++level) {
      request.text(source_level_modes[level]);
      const auto& owners = source_level_owners[level];
      request.scalar(static_cast<std::uint64_t>(owners.size()));
      for (int owner : owners)
        request.scalar(std::int32_t{owner});
    }
    for (std::size_t level = 0; level < target_level_owners.size(); ++level) {
      request.text(target_level_modes[level]);
      const auto& owners = target_level_owners[level];
      request.scalar(static_cast<std::uint64_t>(owners.size()));
      for (int owner : owners)
        request.scalar(std::int32_t{owner});
    }
    request_contract = std::move(request).release();
  } catch (...) {
    validation_error = std::current_exception();
  }
  if (all_reduce_max(validation_error ? 1L : 0L, lane) != 0) {
    if (lane.size() == 1 && validation_error)
      std::rethrow_exception(validation_error);
    throw std::runtime_error("AMR Program rematerialization validation failed collectively");
  }
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-rematerialize-program-state"),
            std::string_view(request_contract)}},
          lane))
    throw std::invalid_argument("AMR Program rematerialization request differs between ranks");
  runtime::program::require_collective_amr_program_checkpoint_consensus(*accepted, lane);
  return runtime::program::serialize_amr_program_accepted_state(*accepted);
}

template <int Dim>
std::vector<int> AmrSystem<Dim>::level_owner_ranks(int level) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  if (level < 0 || static_cast<std::size_t>(level) >= p_->engine->hierarchy().num_levels())
    throw std::out_of_range("AmrSystem owner level is out of range");
  const auto& distribution =
      p_->engine->hierarchy().layout(static_cast<std::size_t>(level)).distribution();
  if (distribution.replicated())
    return {};
  std::vector<int> result;
  result.reserve(distribution.owners().size());
  for (const Index<Dim>& owner : distribution.owners())
    result.push_back(static_cast<int>(distribution.rank_space().linear_rank(owner)));
  return result;
}

template <int Dim>
std::string AmrSystem<Dim>::level_distribution_mode(int level) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  if (level < 0 || static_cast<std::size_t>(level) >= p_->engine->hierarchy().num_levels())
    throw std::out_of_range("AMR distribution level is out of range");
  return p_->engine->hierarchy().layout(static_cast<std::size_t>(level)).distribution().replicated()
             ? "replicated"
             : "partitioned";
}

template <int Dim>
std::vector<std::string> AmrSystem<Dim>::history_names() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  if (!p_->engine)
    return {};
  std::vector<std::string> result;
  for (const auto& descriptor : p_->history_descriptors())
    result.push_back(descriptor.name);
  return result;
}

template <int Dim>
std::vector<int> AmrSystem<Dim>::history_levels(const std::string& name) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  (void)p_->history_descriptor(name);
  std::vector<int> result;
  result.reserve(p_->engine->hierarchy().num_levels());
  for (std::size_t level = 0; level < p_->engine->hierarchy().num_levels(); ++level) {
    (void)p_->history_level_key(name, static_cast<int>(level));
    result.push_back(static_cast<int>(level));
  }
  return result;
}

template <int Dim>
int AmrSystem<Dim>::history_depth(const std::string& name) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  return p_->history_descriptor(name).depth;
}

template <int Dim>
int AmrSystem<Dim>::history_ncomp(const std::string& name) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  return p_->history_descriptor(name).components;
}

template <int Dim>
bool AmrSystem<Dim>::history_initialized(const std::string& name, int level) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  return p_->program.hist_.initialized.at(p_->history_level_key(name, level));
}

template <int Dim>
int AmrSystem<Dim>::history_fill_count(const std::string& name, int level) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  return p_->program.hist_.fill_count.at(p_->history_level_key(name, level));
}

template <int Dim>
void AmrSystem<Dim>::set_history_initialized(const std::string& name, int level, bool initialized) {
  p_->ensure_engine();
  const int fill = initialized ? p_->history_descriptor(name).depth : 0;
  const std::string key = p_->history_level_key(name, level);
  require_amr_history_provenance(p_->program.hist_.slot_dt.at(key),
                                 p_->history_descriptor(name).depth, initialized, fill,
                                 "AMR history initialized restore");
  p_->program.hist_.initialized.at(key) = initialized;
  p_->program.hist_.fill_count.at(key) = fill;
  p_->program.hist_.store_pending.at(key) = false;
}

template <int Dim>
void AmrSystem<Dim>::restore_history_fill_count(const std::string& name, int level,
                                                int fill_count) {
  p_->ensure_engine();
  const int depth = p_->history_descriptor(name).depth;
  if (fill_count < 0 || fill_count > depth)
    throw std::invalid_argument("AMR history fill count lies outside its exact ring depth");
  const std::string key = p_->history_level_key(name, level);
  require_amr_history_provenance(p_->program.hist_.slot_dt.at(key), depth, fill_count > 0,
                                 fill_count, "AMR history fill-count restore");
  p_->program.hist_.fill_count.at(key) = fill_count;
  p_->program.hist_.initialized.at(key) = fill_count > 0;
  p_->program.hist_.store_pending.at(key) = false;
}

template <int Dim>
void AmrSystem<Dim>::restore_history_metadata(const std::string& name, int level, bool initialized,
                                              int fill_count) {
  p_->ensure_engine();
  const int depth = p_->history_descriptor(name).depth;
  if (fill_count < 0 || fill_count > depth)
    throw std::invalid_argument("AMR history fill count lies outside its exact ring depth");
  const std::string key = p_->history_level_key(name, level);
  if (!p_->program.hist_.initialized.contains(key) || !p_->program.hist_.fill_count.contains(key) ||
      !p_->program.hist_.store_pending.contains(key))
    throw std::logic_error("AMR history publication metadata is incomplete");
  require_amr_history_provenance(p_->program.hist_.slot_dt.at(key), depth, initialized, fill_count,
                                 "AMR history metadata restore");
  p_->program.hist_.initialized.at(key) = initialized;
  p_->program.hist_.fill_count.at(key) = fill_count;
  p_->program.hist_.store_pending.at(key) = false;
}

template <int Dim>
void AmrSystem<Dim>::restore_history_provenance(const std::string& name, int level,
                                                const std::vector<double>& slot_dt,
                                                bool initialized, int fill_count) {
  p_->ensure_engine();
  const int depth = p_->history_descriptor(name).depth;
  if (slot_dt.size() != static_cast<std::size_t>(depth))
    throw std::invalid_argument("AMR history provenance differs from its exact ring depth");
  std::vector<Real> candidate;
  candidate.reserve(slot_dt.size());
  for (const double value : slot_dt) {
    const Real native = static_cast<Real>(value);
    if (!std::isfinite(value) || !std::isfinite(static_cast<double>(native)))
      throw std::invalid_argument("AMR history provenance has a non-finite outgoing dt");
    candidate.push_back(native);
  }
  require_amr_history_provenance(candidate, depth, initialized, fill_count,
                                 "AMR history provenance restore");
  const std::string key = p_->history_level_key(name, level);
  auto candidate_slot_dt = p_->program.hist_.slot_dt.find(key);
  if (!p_->program.hist_.initialized.contains(key) || !p_->program.hist_.fill_count.contains(key) ||
      !p_->program.hist_.store_pending.contains(key) ||
      candidate_slot_dt == p_->program.hist_.slot_dt.end() ||
      candidate_slot_dt->second.size() != static_cast<std::size_t>(depth))
    throw std::logic_error("AMR history publication metadata is incomplete");
  static_assert(std::is_nothrow_swappable_v<std::vector<Real>>);
  candidate_slot_dt->second.swap(candidate);
  p_->program.hist_.initialized.at(key) = initialized;
  p_->program.hist_.fill_count.at(key) = fill_count;
  p_->program.hist_.store_pending.at(key) = false;
}

template <int Dim>
std::vector<double> AmrSystem<Dim>::history_global(const std::string& name, int level,
                                                   int slot) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  const ExecutionLane& lane = p_->require_prepared_engine_lane("AMR history gather");
  const MultiFab<Dim>* history = nullptr;
  const Box<Dim>* domain = nullptr;
  int components = 0;
  std::string semantic_identity;
  std::exception_ptr local_error;
  try {
    const auto descriptor = p_->history_descriptor(name);
    if (slot < 0 || slot >= descriptor.depth)
      throw std::out_of_range("AMR history slot lies outside its exact ring depth");
    const std::string key = p_->history_level_key(name, level);
    const auto& ring = p_->program.hist_.histories.at(key);
    history = &ring.at(static_cast<std::size_t>(slot));
    domain = &p_->engine->hierarchy().layout(static_cast<std::size_t>(level)).domain();
    components = descriptor.components;
    ExactContractBuilder exact;
    exact.text("pops.amr.history-gather")
        .scalar(std::uint32_t{1})
        .text(key)
        .scalar(std::int32_t{slot});
    semantic_identity = std::move(exact).release();
  } catch (...) {
    local_error = std::current_exception();
  }
  runtime::system::auxiliary_ghost_detail::rethrow_collective_failure(
      local_error, &lane, "AMR history gather preflight failed collectively");
  return gather_field(*history, *domain, components, semantic_identity, lane);
}

template <int Dim>
void AmrSystem<Dim>::restore_history(const std::string& name, int level, int slot,
                                     const std::vector<double>& values) {
  p_->ensure_engine();
  const auto descriptor = p_->history_descriptor(name);
  if (slot < 0 || slot >= descriptor.depth)
    throw std::out_of_range("AMR history slot lies outside its exact ring depth");
  const std::string key = p_->history_level_key(name, level);
  const std::size_t cells =
      checked_cells(p_->engine->hierarchy().layout(static_cast<std::size_t>(level)).domain());
  const std::size_t expected =
      checked_size_product(cells, static_cast<std::size_t>(descriptor.components),
                           "AMR history restore level size overflow");
  if (values.size() != expected)
    throw std::invalid_argument("AMR history restore payload has the wrong exact-ranked size");
  auto& field = p_->program.hist_.histories.at(key)[static_cast<std::size_t>(slot)];
  write_field(field, p_->engine->hierarchy().layout(static_cast<std::size_t>(level)).domain(),
              values, descriptor.components);
}

template <int Dim>
double AmrSystem<Dim>::history_slot_dt(const std::string& name, int level, int slot) const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  const int depth = p_->history_descriptor(name).depth;
  if (slot < 0 || slot >= depth)
    throw std::out_of_range("AMR history dt slot lies outside its exact ring depth");
  const auto& values = p_->program.hist_.slot_dt.at(p_->history_level_key(name, level));
  if (values.size() != static_cast<std::size_t>(depth))
    throw std::logic_error("AMR history dt ledger differs from its exact ring depth");
  return static_cast<double>(values[static_cast<std::size_t>(slot)]);
}

template <int Dim>
void AmrSystem<Dim>::restore_history_slot_dt(const std::string& name, int level, int slot,
                                             double dt) {
  p_->ensure_engine();
  const int depth = p_->history_descriptor(name).depth;
  if (slot < 0 || slot >= depth || !std::isfinite(dt) || dt < 0.0)
    throw std::invalid_argument("AMR history dt restore requires a valid slot and finite dt >= 0");
  const Real native_dt = static_cast<Real>(dt);
  if (!std::isfinite(static_cast<double>(native_dt)))
    throw std::overflow_error("AMR history dt exceeds native Real");
  const std::string key = p_->history_level_key(name, level);
  std::vector<Real> candidate = p_->program.hist_.slot_dt.at(key);
  candidate[static_cast<std::size_t>(slot)] = native_dt;
  require_amr_history_provenance(candidate, depth, p_->program.hist_.initialized.at(key),
                                 p_->program.hist_.fill_count.at(key),
                                 "AMR history outgoing-dt restore");
  p_->program.hist_.slot_dt.at(key).swap(candidate);
}

template <int Dim>
int AmrSystem<Dim>::rebuild_history_slots(const std::string& name,
                                          const std::vector<int>& stored_slots) {
  p_->ensure_engine();
  const auto descriptor = p_->history_descriptor(name);
  if (!p_->program.step_)
    throw std::logic_error("AMR history replay requires an installed compiled Program");
  if (!p_->program.authorizes_history_replay(name, descriptor.depth))
    throw std::logic_error("AMR history selective replay lacks its exact artifact-owned authority");
  if (p_->program.substeps_ != 1 || p_->program.stride_ != 1)
    throw std::logic_error(
        "AMR history selective replay requires Program cadence (substeps=1, stride=1)");

  std::vector<int> anchors = stored_slots;
  std::sort(anchors.begin(), anchors.end());
  anchors.erase(std::unique(anchors.begin(), anchors.end()), anchors.end());
  if (anchors.empty() || anchors.front() != 0 || anchors.back() != descriptor.depth - 1)
    throw std::invalid_argument(
        "AMR history selective replay requires exact newest and oldest anchors");
  for (const int anchor : anchors)
    if (anchor < 0 || anchor >= descriptor.depth)
      throw std::out_of_range("AMR history selective replay anchor is outside the ring");
  if (static_cast<int>(anchors.size()) == descriptor.depth) {
    p_->last_replay_regrid_steps.clear();
    return 0;
  }
  if (p_->cfg.regrid_every > 0)
    for (int slot = descriptor.depth - 2; slot >= 0; --slot) {
      const int cursor = p_->macro_step - 1 - slot;
      if (cursor > 0 && cursor % p_->cfg.regrid_every == 0)
        throw std::logic_error(
            "AMR history selective replay window contains a scheduled regrid; use dense safety "
            "storage");
    }

  const auto keys = p_->history_level_keys(name);
  const int runtime_owner = p_->program.hist_.owner.at(keys.front());
  if (runtime_owner < 0 || static_cast<std::size_t>(runtime_owner) >= p_->blocks.size())
    throw std::logic_error("AMR history replay has an invalid runtime block owner");
  for (const std::string& key : keys)
    if (p_->program.hist_.owner.at(key) != runtime_owner)
      throw std::logic_error("AMR history replay changes runtime block owner across levels");
  const std::size_t block_index = static_cast<std::size_t>(runtime_owner);
  std::vector<Real> dts = p_->program.hist_.slot_dt.at(keys.front());
  for (std::size_t anchor = 0; anchor + 1 < anchors.size(); ++anchor)
    for (int slot = anchors[anchor + 1] - 1; slot > anchors[anchor]; --slot)
      if (slot + 1 >= static_cast<int>(dts.size()) ||
          !std::isfinite(static_cast<double>(dts[static_cast<std::size_t>(slot + 1)])) ||
          !(dts[static_cast<std::size_t>(slot + 1)] > Real(0)))
        throw std::invalid_argument(
            "AMR history selective replay requires every omitted outgoing dt");

  std::unique_ptr<typename Impl::AcceptedSnapshot> accepted =
      p_->prepare_accepted_snapshot_collectively("history selective replay");
  std::vector<std::vector<MultiFab<Dim>>> reconstructed(static_cast<std::size_t>(descriptor.depth));
  std::vector<int> fired;
  try {
    for (std::size_t anchor = 0; anchor + 1 < anchors.size(); ++anchor) {
      const int newer = anchors[anchor];
      const int older = anchors[anchor + 1];
      accepted->restore(*p_);
      for (std::size_t level = 0; level < keys.size(); ++level)
        copy_full_field_in_place(
            p_->program.hist_.histories.at(keys[level])[static_cast<std::size_t>(older)],
            p_->block_state(block_index, level));
      for (int slot = older - 1; slot > newer; --slot) {
        const int cursor = p_->macro_step - 1 - slot;
        p_->macro_step = cursor;
        const std::uint64_t epoch = p_->engine->topology_epoch();
        p_->program.replay_step(static_cast<double>(dts[static_cast<std::size_t>(slot + 1)]),
                                "AmrSystem::rebuild_history_slots");
        if (p_->engine->topology_epoch() != epoch)
          fired.push_back(cursor);
        auto& image = reconstructed[static_cast<std::size_t>(slot)];
        image.reserve(keys.size());
        for (std::size_t level = 0; level < keys.size(); ++level)
          image.push_back(p_->block_state(block_index, level));
      }
    }
  } catch (...) {
    accepted->restore(*p_);
    throw;
  }
  accepted->restore(*p_);
  if (!fired.empty())
    throw std::logic_error(
        "AMR history selective replay changed topology; use dense safety storage");

  int recomputed = 0;
  for (int slot = 0; slot < descriptor.depth; ++slot) {
    if (std::binary_search(anchors.begin(), anchors.end(), slot))
      continue;
    const auto& image = reconstructed[static_cast<std::size_t>(slot)];
    if (image.size() != keys.size())
      throw std::logic_error("AMR history anchors do not bracket every omitted slot");
    for (std::size_t level = 0; level < keys.size(); ++level)
      copy_full_field_in_place(image[level], p_->program.hist_.histories.at(
                                                 keys[level])[static_cast<std::size_t>(slot)]);
    ++recomputed;
  }
  p_->last_replay_regrid_steps.clear();
  return recomputed;
}

template <int Dim>
std::vector<int> AmrSystem<Dim>::last_replay_regrid_steps() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  return p_->last_replay_regrid_steps;
}

template <int Dim>
double AmrSystem<Dim>::mass() {
  if (p_->blocks.empty())
    throw std::logic_error("AmrSystem has no block");
  return mass(p_->blocks.front().name);
}

template <int Dim>
double AmrSystem<Dim>::mass(const std::string& name) {
  return composite_reduce(name, "sum", 0);
}

template <int Dim>
std::vector<double> AmrSystem<Dim>::density() {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->require_no_native_package_callback("density");
  const ExecutionLane& package_lane = p_->require_package_assembly_lane();
  std::string block_name;
  std::exception_ptr local_error;
  try {
    if (p_->blocks.empty())
      throw std::logic_error("AmrSystem has no block");
    block_name = p_->blocks.front().name;
  } catch (...) {
    local_error = std::current_exception();
  }
  runtime::system::auxiliary_ghost_detail::rethrow_collective_failure(
      local_error, &package_lane, "AMR default density route failed collectively");
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-default-density-block"), block_name}}, package_lane))
    throw std::invalid_argument("AMR default density block differs between RuntimeInstance ranks");
  return density(block_name);
}

template <int Dim>
std::vector<double> AmrSystem<Dim>::density(const std::string& name) {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  p_->ensure_engine();
  const ExecutionLane& lane = p_->require_prepared_engine_lane("AMR density gather");
  std::size_t block_index = 0;
  std::string semantic_identity;
  std::exception_ptr local_error;
  try {
    block_index = p_->block_index(name);
    ExactContractBuilder exact;
    exact.text("pops.amr.density-gather")
        .scalar(std::uint32_t{1})
        .text(name)
        .scalar(static_cast<std::uint64_t>(block_index));
    semantic_identity = std::move(exact).release();
  } catch (...) {
    local_error = std::current_exception();
  }
  runtime::system::auxiliary_ghost_detail::rethrow_collective_failure(
      local_error, &lane, "AMR density gather preflight failed collectively");
  return gather_field(p_->block_state(block_index, 0), p_->cfg.index_domain(), 1, semantic_identity,
                      lane);
}

template <int Dim>
std::pair<std::size_t, std::size_t> AmrSystem<Dim>::checkpoint_program_state_capacity() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  return program_checkpoint_state_capacity_();
}

template <int Dim>
std::pair<std::size_t, std::size_t> AmrSystem<Dim>::program_checkpoint_state_capacity_() const {
  const bool preparing_candidate = p_->active_checkpoint_capacity_authority != nullptr;
  // The capacity pair is constructed, cross-rank authenticated and published with POPSAND5
  // before the Program DSO owner becomes reachable.  After that exchange it is an immutable
  // accepted-authority witness: bind and public inspection must not rebuild the arithmetic from
  // whichever Program happened to be live before a replacement candidate was installed.
  if (!preparing_candidate) {
    if (!p_->checkpoint_program_state_capacity_value ||
        p_->checkpoint_program_state_capacity_contract.empty())
      throw std::logic_error(
          "AMR Program checkpoint capacity was not published by its prepared installation");
    return *p_->checkpoint_program_state_capacity_value;
  }
  const typename Impl::ProgramCheckpointCapacityAuthority authority =
      p_->checkpoint_capacity_authority();
  const typename Impl::engine_type* capacity_engine = authority.engine;
  const typename Impl::multiblock_type* capacity_multiblock = authority.multiblock;
  const typename Impl::PreparedHierarchy* capacity_hierarchy = authority.hierarchy;
  const runtime::program::ProgramRuntimeState<Dim>* capacity_program = authority.program;
  const typename Impl::multiblock_type::ProgramBlockMap* capacity_block_map =
      authority.program_block_map;
  if (!capacity_engine || !capacity_multiblock || !capacity_hierarchy ||
      !capacity_hierarchy->lane || !capacity_program || !authority.flux_budget ||
      !authority.metadata || !authority.installed_hash || !authority.accepted_bytes ||
      !authority.config || !authority.temporal_relations || !authority.tagging_spec ||
      !authority.block_identities)
    throw std::logic_error(
        "AMR Program checkpoint capacity requires its already prepared hierarchy lane");
  const AmrSystemConfig<Dim>& configuration = *authority.config;
  const auto& relations = *authority.temporal_relations;
  const auto& tagger = *authority.tagging_spec;
  const auto& block_identities = *authority.block_identities;
  const ExecutionLane& lane = *capacity_hierarchy->lane;
  std::optional<std::pair<std::size_t, std::size_t>> candidate;
  std::string candidate_contract;
  std::exception_ptr local_error;
  try {
    const std::size_t configured_levels = static_cast<std::size_t>(configuration.level_count);
    const std::size_t active_levels = capacity_engine->hierarchy().num_levels();
    const std::string& installed_hash = *authority.installed_hash;
    if ((!preparing_candidate && !capacity_program->artifact_backed_) || installed_hash.empty() ||
        configured_levels == 0 || active_levels == 0 || active_levels > configured_levels ||
        configuration.transition_ratios.size() + 1 != configured_levels ||
        relations.size() + 1 != configured_levels)
      throw std::logic_error(
          "AMR Program checkpoint capacity lacks its frozen artifact/hierarchy authority");
    const auto& metadata = *authority.metadata;
    if (metadata.logical_clock_identities.empty() || metadata.temporal_provider_identity.empty())
      throw std::logic_error("AMR Program checkpoint capacity lacks frozen Program metadata");
    if (metadata.temporal_provider_identity ==
        runtime::program::kSameLevelTransportEulerStageFluxProvider) {
      if (metadata.temporal_cell_capacity != 0 ||
          metadata.temporal_cells_per_topology_cell != block_identities.size() ||
          capacity_program->block_map_.size() != block_identities.size() ||
          capacity_block_map == nullptr ||
          capacity_block_map->canonical_indices.size() != block_identities.size())
        throw std::logic_error(
            "AMR Program cell-local checkpoint capacity lacks its exact route/block authority");
      std::vector<bool> seen(block_identities.size(), false);
      for (std::size_t program = 0; program < capacity_program->block_map_.size(); ++program) {
        const int runtime_block = capacity_program->block_map_[program];
        const std::size_t canonical = capacity_block_map->canonical_indices[program];
        if (runtime_block < 0 || static_cast<std::size_t>(runtime_block) != canonical ||
            canonical >= seen.size() || seen[canonical])
          throw std::logic_error(
              "AMR Program cell-local checkpoint routes differ from the prepared block map");
        seen[canonical] = true;
      }
    } else if (metadata.temporal_provider_identity !=
               runtime::program::kGlobalTemporalPartitionProvider) {
      throw std::logic_error(
          "AMR Program temporal checkpoint capacity has no native provider authority");
    }

    std::vector<std::size_t> level_cells;
    level_cells.reserve(configured_levels);
    Box<Dim> level_domain = configuration.index_domain();
    for (std::size_t level = 0; level < configured_levels; ++level) {
      if (level != 0)
        level_domain = amr::hierarchy::refine_box(
            level_domain, refinement_ratio(configuration.transition_ratios[level - 1]));
      level_cells.push_back(checked_cells(level_domain));
    }
    std::size_t configured_cells = 0;
    for (const std::size_t cells : level_cells)
      configured_cells = checked_size_sum(configured_cells, cells,
                                          "AMR configured checkpoint cells exceed size_t");
    std::size_t effective_temporal_cells = metadata.temporal_cell_capacity;
    if (metadata.temporal_cells_per_topology_cell != 0) {
      effective_temporal_cells =
          checked_size_product(configured_cells, metadata.temporal_cells_per_topology_cell,
                               "AMR Program temporal checkpoint capacity exceeds size_t");
    }
    if (metadata.temporal_cell_capacity != 0 && metadata.temporal_cells_per_topology_cell != 0)
      throw std::logic_error(
          "AMR Program temporal checkpoint metadata mixes absolute and topology-relative shapes");
    if (effective_temporal_cells >
        checked_size_product(configured_cells, std::max<std::size_t>(block_identities.size(), 1),
                             "AMR configured checkpoint route cells exceed size_t"))
      throw std::logic_error(
          "AMR Program temporal checkpoint capacity exceeds its configured domains");
    if (metadata.temporal_provider_identity == runtime::program::kGlobalTemporalPartitionProvider &&
        metadata.temporal_cell_capacity != 0)
      throw std::logic_error(
          "global AMR Program temporal checkpoint metadata carries cell-local capacity");

    runtime::program::AmrProgramAcceptedStateCapacity<Dim> shape;
    // ExactContractBuilder framing is fixed-width.  One-cell patches/owners maximize the spatial
    // contract for any conservative regrid inside the configured domains without materializing a
    // speculative hierarchy merely to count its bytes.
    constexpr std::size_t frame = 1 + sizeof(std::uint64_t);
    constexpr std::size_t scalar_i32 = frame + 2 + sizeof(std::int32_t);
    constexpr std::size_t scalar_u32 = frame + 2 + sizeof(std::uint32_t);
    constexpr std::size_t scalar_u64 = frame + 2 + sizeof(std::uint64_t);
    constexpr std::size_t scalar_enum_i32 = frame + 1 + 2 + sizeof(std::int32_t);
    const auto add_spatial = [&](std::size_t& bytes, std::size_t value) {
      bytes =
          checked_size_sum(bytes, value, "AMR Program spatial-contract capacity exceeds size_t");
    };
    std::size_t spatial = 0;
    std::vector<std::uint64_t> configured_spatial_contract_characters_by_level;
    configured_spatial_contract_characters_by_level.reserve(configured_levels);
    add_spatial(spatial, frame + std::string_view("pops.amr-runtime-spatial-contract").size());
    add_spatial(spatial, 2 * scalar_u32);
    add_spatial(spatial, frame + capacity_engine->spatial_identity().size());
    add_spatial(spatial, 6 * scalar_u64);
    for (const std::size_t cells : level_cells) {
      add_spatial(spatial, scalar_i32);
      add_spatial(spatial,
                  checked_size_product(static_cast<std::size_t>(6 * Dim), scalar_i32,
                                       "AMR Program spatial-contract capacity exceeds size_t"));
      add_spatial(spatial, scalar_enum_i32);
      add_spatial(spatial, scalar_i32);
      add_spatial(spatial, 2 * scalar_u64);
      std::size_t patch_entry = checked_size_sum(
          frame,
          checked_size_product(static_cast<std::size_t>(2 * Dim), scalar_i32,
                               "AMR Program spatial-contract capacity exceeds size_t"),
          "AMR Program spatial-contract capacity exceeds size_t");
      std::size_t owner_entry = checked_size_sum(
          frame,
          checked_size_product(static_cast<std::size_t>(Dim), scalar_i32,
                               "AMR Program spatial-contract capacity exceeds size_t"),
          "AMR Program spatial-contract capacity exceeds size_t");
      add_spatial(spatial, 2 * frame + 2 * sizeof(std::uint64_t));
      add_spatial(spatial,
                  checked_size_product(cells, patch_entry,
                                       "AMR Program spatial-contract capacity exceeds size_t"));
      add_spatial(spatial,
                  checked_size_product(cells, owner_entry,
                                       "AMR Program spatial-contract capacity exceeds size_t"));
      configured_spatial_contract_characters_by_level.push_back(
          static_cast<std::uint64_t>(spatial));
    }
    shape.spatial_contract_characters = spatial;
    shape.level_count = configured_levels;
    shape.logical_clock_identities = metadata.logical_clock_identities;
    shape.histories.reserve(metadata.histories.size());
    for (const auto& row : metadata.histories)
      shape.histories.push_back({row.name, row.program_owner, row.state_identity,
                                 row.space_identity, row.clock_identity, row.interpolation_identity,
                                 row.depth, row.components});
    shape.temporal_provider_identity = metadata.temporal_provider_identity;
    shape.temporal_cell_count = effective_temporal_cells;

    if (tagger && tagger->min_cycles > 0) {
      std::size_t parent_cells = 0;
      for (std::size_t level = 0; level + 1 < configured_levels; ++level)
        parent_cells = checked_size_sum(parent_cells, level_cells[level],
                                        "AMR tagging checkpoint cells exceed size_t");
      constexpr std::size_t tagging_fixed_bytes =
          8 + 2 * sizeof(std::uint32_t) + 3 * sizeof(std::uint64_t);
      constexpr std::size_t tagging_record_bytes =
          sizeof(std::int32_t) * (1u + Dim) + sizeof(std::uint64_t) + sizeof(std::uint8_t);
      shape.tagging_hysteresis_bytes =
          checked_size_sum(checked_size_sum(tagging_fixed_bytes, tagger->provider_identity.size(),
                                            "AMR tagging checkpoint capacity exceeds size_t"),
                           checked_size_product(parent_cells, tagging_record_bytes,
                                                "AMR tagging checkpoint capacity exceeds size_t"),
                           "AMR tagging checkpoint capacity exceeds size_t");
    }

    constexpr std::string_view flux_contract_prefix =
        "pops.amr-program.complete-flux-budget.v1:sha256:";
    constexpr std::string_view coupling_contract_prefix =
        "pops.amr-program.accepted-coupling.v1:sha256:";
    shape.flux_budget_contract_characters = flux_contract_prefix.size() + 64;
    shape.coupling_contract_characters = coupling_contract_prefix.size() + 64;

    const auto& expression = *authority.flux_budget;
    const auto interface = p_->configured_interface_flux_ledger_budget_envelope(configured_levels);
    const auto interface_production =
        p_->prepared_interface_flux_production_budget(configured_levels);
    std::size_t rhs_basis = 0;
    std::size_t coefficient_terms = 0;
    std::size_t maximum_components = 1;
    std::size_t maximum_owner_identity = 1;
    for (std::size_t program_block = 0; program_block < expression.blocks.size(); ++program_block) {
      rhs_basis = checked_size_sum(rhs_basis, expression.blocks[program_block].rhs_basis_bound,
                                   "AMR face-ledger basis capacity exceeds size_t");
      coefficient_terms =
          std::max(coefficient_terms, expression.blocks[program_block].coefficient_term_bound);
      const std::size_t runtime_block =
          expression.program_block_map.canonical_indices.at(program_block);
      maximum_components = std::max(
          maximum_components, static_cast<std::size_t>(block_identities.at(runtime_block).ncomp));
      maximum_owner_identity = std::max(maximum_owner_identity,
                                        capacity_multiblock->block_identity(runtime_block).size());
    }
    std::size_t face_fragments = 0;
    std::size_t executions = 1;
    for (std::size_t parent = 0; parent + 1 < configured_levels; ++parent) {
      const auto temporal = relations[parent].temporal_ratio();
      const std::size_t substeps =
          static_cast<std::size_t>(temporal.numerator / temporal.denominator +
                                   (temporal.numerator % temporal.denominator == 0 ? 0 : 1));
      const auto ratio = refinement_ratio(configuration.transition_ratios[parent]);
      std::size_t maximum_fine_faces = 1;
      for (int axis = 0; axis < Dim; ++axis) {
        std::size_t fine_faces = 1;
        for (int tangent = 0; tangent < Dim; ++tangent)
          if (tangent != axis)
            fine_faces = checked_size_product(fine_faces, static_cast<std::size_t>(ratio[tangent]),
                                              "AMR face-ledger fine-face capacity exceeds size_t");
        maximum_fine_faces = std::max(maximum_fine_faces, fine_faces);
      }
      const std::size_t fine_evaluations = checked_size_product(
          substeps, maximum_fine_faces, "AMR face-ledger fine-evaluation capacity exceeds size_t");
      const std::size_t coarse_faces =
          checked_size_product(level_cells[parent], static_cast<std::size_t>(2 * Dim),
                               "AMR face-ledger interface capacity exceeds size_t");
      std::size_t level_fragments = checked_size_product(
          executions, rhs_basis, "AMR face-ledger fragment capacity exceeds size_t");
      level_fragments = checked_size_product(level_fragments, coarse_faces,
                                             "AMR face-ledger fragment capacity exceeds size_t");
      level_fragments = checked_size_product(
          level_fragments,
          checked_size_sum(fine_evaluations, 1, "AMR face-ledger fragment capacity exceeds size_t"),
          "AMR face-ledger fragment capacity exceeds size_t");
      face_fragments = checked_size_sum(face_fragments, level_fragments,
                                        "AMR face-ledger fragment capacity exceeds size_t");
      executions = checked_size_product(executions, substeps,
                                        "AMR face-ledger execution capacity exceeds size_t");
    }
    constexpr std::size_t unsigned_decimal_characters =
        std::numeric_limits<std::uint64_t>::digits10 + 1;
    constexpr std::size_t signed_decimal_characters =
        std::numeric_limits<std::int64_t>::digits10 + 2;
    constexpr std::size_t nonnegative_int_decimal_characters =
        std::numeric_limits<int>::digits10 + 1;
    shape.face_fragment_counts[0] = face_fragments;
    shape.face_owner_characters = maximum_owner_identity;
    shape.face_state_characters =
        checked_size_sum(maximum_owner_identity, std::string_view("/state").size(),
                         "AMR face-ledger identity capacity exceeds size_t");
    // This is the exact grammar emitted by materialize_active_flux_expression_(). The provider
    // range is closed by FluxBasisProvider; successful active allocations are numbered 1 through
    // the frozen aggregate RHS-basis bound, while an inactive zero-bound image emits no basis.
    const std::size_t maximum_basis_identity = rhs_basis == 0 ? 0 : rhs_basis;
    const std::size_t basis_identity_characters = std::to_string(maximum_basis_identity).size();
    // FluxBasisProvider is a closed POPSAND5 wire enum with its greatest emitted value NamedCell=3.
    constexpr std::size_t provider_characters = std::string_view("3").size();
    std::size_t face_stage_characters = 0;
    const auto add_face_stage_characters = [&](std::size_t characters) {
      face_stage_characters =
          checked_size_sum(face_stage_characters, characters,
                           "AMR face-ledger stage identity capacity exceeds size_t");
    };
    add_face_stage_characters(std::string_view("pops.program-flux-expression.v1/provider/").size());
    add_face_stage_characters(provider_characters);
    add_face_stage_characters(std::string_view("/rhs/").size());
    add_face_stage_characters(nonnegative_int_decimal_characters);
    add_face_stage_characters(std::string_view("/point-stage/").size());
    add_face_stage_characters(nonnegative_int_decimal_characters);
    add_face_stage_characters(std::string_view("/basis/").size());
    add_face_stage_characters(basis_identity_characters);
    add_face_stage_characters(std::string_view("/dt-power/1/weight/").size());
    add_face_stage_characters(signed_decimal_characters);
    add_face_stage_characters(1);  // slash between the exact rational numerator and denominator
    add_face_stage_characters(signed_decimal_characters);
    add_face_stage_characters(std::string_view("/stage/").size());
    add_face_stage_characters(signed_decimal_characters);
    add_face_stage_characters(
        1);  // slash between the exact stage-fraction numerator and denominator
    add_face_stage_characters(signed_decimal_characters);
    shape.face_stage_characters = face_stage_characters;
    shape.face_payload_terms = checked_size_product(
        face_fragments, maximum_components, "AMR face-ledger payload capacity exceeds size_t");

    // History-flux provenance uses the same frozen basis/face envelope as the accepted ledger.
    // Count its actual POPSAND5 primitives, including every level-qualified ring key and every
    // slot/term count; this is a capacity proof, not an opaque reserve.
    std::size_t maximum_clock_identity = 1;
    for (const std::string& identity : metadata.logical_clock_identities)
      maximum_clock_identity = std::max(maximum_clock_identity, identity.size());
    for (const auto& history : shape.histories)
      maximum_clock_identity = std::max(maximum_clock_identity, history.clock_identity.size());
    // History FluxBasis points are constructed only by boundary_evaluation_point(), whose graph,
    // rate, and application identities are empty.  Interface-coupling identity capacity governs
    // a different wire family and cannot be used as authority for these three point strings.
    constexpr std::size_t history_flux_point_extra_identity_characters = 0;
    // Writer::i32 is intentionally an eight-byte wire integer.  Keep the expression below in
    // Writer primitives so a future wire-width change cannot leave an uncounted reserve.
    const std::size_t history_flux_point = checked_size_sum(
        checked_size_sum(4 * sizeof(std::uint64_t), maximum_clock_identity,
                         "AMR history-flux point capacity exceeds size_t"),
        checked_size_sum(8 * sizeof(std::uint64_t),
                         checked_size_product(3, history_flux_point_extra_identity_characters,
                                              "AMR history-flux point capacity exceeds size_t"),
                         "AMR history-flux point capacity exceeds size_t"),
        "AMR history-flux point capacity exceeds size_t");
    const std::size_t history_flux_fixed_basis = checked_size_sum(
        checked_size_sum(4 * sizeof(std::uint64_t), history_flux_point,
                         "AMR history-flux basis capacity exceeds size_t"),
        checked_size_sum(2 * runtime::program::checkpoint_detail::kEncodedClockBytes,
                         sizeof(std::uint64_t), "AMR history-flux basis capacity exceeds size_t"),
        "AMR history-flux basis capacity exceeds size_t");
    const std::size_t history_flux_coefficient =
        checked_size_product(coefficient_terms, sizeof(std::int64_t) * 3,
                             "AMR history-flux coefficient capacity exceeds size_t");
    const std::size_t history_flux_face = checked_size_sum(
        3 * sizeof(std::uint64_t) + sizeof(double),
        checked_size_sum(
            checked_size_product(static_cast<std::size_t>(2 * Dim), sizeof(std::int64_t),
                                 "AMR history-flux face capacity exceeds size_t"),
            checked_size_product(maximum_components, sizeof(double),
                                 "AMR history-flux payload capacity exceeds size_t"),
            "AMR history-flux face capacity exceeds size_t"),
        "AMR history-flux face capacity exceeds size_t");
    const std::size_t history_flux_basis = checked_size_sum(
        2 * sizeof(std::uint64_t),  // basis identity and coefficient count
        checked_size_sum(
            history_flux_fixed_basis,
            checked_size_sum(history_flux_coefficient,
                             checked_size_product(face_fragments, history_flux_face,
                                                  "AMR history-flux face capacity exceeds size_t"),
                             "AMR history-flux basis capacity exceeds size_t"),
            "AMR history-flux basis capacity exceeds size_t"),
        "AMR history-flux basis capacity exceeds size_t");
    shape.history_flux_payload_bytes = sizeof(std::uint64_t);  // history-ring count
    constexpr std::string_view history_key_prefix = "pops.amr.level-history.v1/";
    for (const auto& history : shape.histories) {
      const std::string history_length = std::to_string(history.name.size());
      for (std::size_t level = 0; level < configured_levels; ++level) {
        const std::string level_text = std::to_string(level);
        const std::size_t key_characters =
            checked_size_sum(checked_size_sum(history_key_prefix.size(), level_text.size(),
                                              "AMR history-flux key capacity exceeds size_t"),
                             checked_size_sum(1 + history_length.size(), 1 + history.name.size(),
                                              "AMR history-flux key capacity exceeds size_t"),
                             "AMR history-flux key capacity exceeds size_t");
        const std::size_t ring_bytes = checked_size_sum(
            checked_size_sum(sizeof(std::uint64_t), key_characters,
                             "AMR history-flux key capacity exceeds size_t"),
            sizeof(std::uint64_t), "AMR history-flux ring capacity exceeds size_t");
        shape.history_flux_payload_bytes =
            checked_size_sum(shape.history_flux_payload_bytes, ring_bytes,
                             "AMR history-flux payload capacity exceeds size_t");
        for (int slot = 0; slot < history.depth; ++slot) {
          const std::size_t slot_bytes = checked_size_sum(
              sizeof(std::uint64_t),
              checked_size_product(rhs_basis, history_flux_basis,
                                   "AMR history-flux basis capacity exceeds size_t"),
              "AMR history-flux slot capacity exceeds size_t");
          shape.history_flux_payload_bytes =
              checked_size_sum(shape.history_flux_payload_bytes, slot_bytes,
                               "AMR history-flux payload capacity exceeds size_t");
        }
      }
    }
    // One direct-child deferred AB2 remap can exist per logical ring and configured transition.
    // Its key is the canonical level-qualified history key; derive its bounded characters from
    // the same frozen descriptor rather than reserving opaque slack.
    shape.pending_history_remap_count =
        checked_size_product(shape.histories.size(), configured_levels - 1,
                             "AMR pending history-remap capacity exceeds size_t");
    for (const auto& history : shape.histories) {
      const std::size_t key_characters = std::string_view("pops.amr.level-history.v1/").size() +
                                         unsigned_decimal_characters + 1 +
                                         unsigned_decimal_characters + 1 + history.name.size();
      shape.pending_history_remap_key_characters =
          std::max(shape.pending_history_remap_key_characters, key_characters);
    }

    shape.interface_fragment_count = interface.max_fragments_per_window;
    shape.interface_identity_characters =
        interface_production.maximum_interface_identity_characters;
    shape.interface_program_identity_characters = checked_size_product(
        interface.max_fragments_per_window, expression.interface_coupling_identity_character_bound,
        "AMR interface Program identity capacity exceeds size_t");
    shape.interface_stage_characters =
        std::string_view("program-stage:").size() + 2 * signed_decimal_characters + 1;
    shape.interface_payload_terms = interface.max_payload_terms_per_window;
    shape.synchronization_event_count = checked_size_product(
        checked_size_product(block_identities.size(), configured_levels - 1,
                             "AMR synchronization checkpoint capacity exceeds size_t"),
        2, "AMR synchronization checkpoint capacity exceeds size_t");
    shape.synchronization_phase_characters = std::string_view("average_down").size();

    const std::size_t accepted =
        runtime::program::serialized_amr_program_accepted_state_capacity(shape);
    constexpr std::string_view source_authority_prefix =
        "pops.amr-program.accepted-source-authority.v2:sha256:";
    constexpr std::size_t source_authority_bytes = source_authority_prefix.size() + 64;

    // The live prelude is evidence, never the capacity source.  It must be an exact subset of the
    // frozen DSO shape and already fit the independently counted configured-depth envelope.
    const std::vector<std::uint8_t>& live_bytes = *authority.accepted_bytes;
    if (!live_bytes.empty()) {
      const auto live =
          runtime::program::deserialize_amr_program_accepted_state<Dim>(live_bytes, &interface);
      std::vector<std::string> live_clocks;
      live_clocks.reserve(live.logical_clock_ticks.size());
      for (const auto& [identity, tick] : live.logical_clock_ticks) {
        (void)tick;
        live_clocks.push_back(identity);
      }
      const bool histories_match = live.histories == shape.histories;
      const bool clocks_match = live_clocks == shape.logical_clock_identities;
      const bool provider_matches =
          live.temporal_partition.provider_identity == shape.temporal_provider_identity;
      const bool temporal_cells_fit =
          live.temporal_partition.cells.size() <= shape.temporal_cell_count;
      const bool bytes_fit = live_bytes.size() <= accepted;
      if (!histories_match || !clocks_match || !provider_matches || !temporal_cells_fit ||
          !bytes_fit) {
        // This is a bind-time authority failure.  Keep the individual witnesses in the diagnostic:
        // collapsing them made a stale checkpoint envelope indistinguishable from an invalid live
        // Program state and invited callers to weaken the seal instead of repairing its order.
        const auto identities = [](const std::vector<std::string>& values) {
          std::string result;
          for (const std::string& value : values) {
            if (!result.empty())
              result += ',';
            result += value;
          }
          return result;
        };
        std::string message =
            "live AMR Program checkpoint state differs from its frozen capacity metadata "
            "(histories=";
        message += std::to_string(histories_match);
        message += ":";
        message += std::to_string(live.histories.size());
        message += "/";
        message += std::to_string(shape.histories.size());
        message += "[";
        for (const auto& history : live.histories) {
          if (message.back() != '[')
            message += ',';
          message += history.name;
        }
        message += "]/[";
        for (const auto& history : shape.histories) {
          if (message.back() != '[')
            message += ',';
          message += history.name;
        }
        message += "]";
        message += ", clocks=";
        message += std::to_string(clocks_match);
        message += ", provider=";
        message += std::to_string(provider_matches);
        message += ", temporal-cells=";
        message += std::to_string(temporal_cells_fit);
        message += ", bytes=";
        message += std::to_string(bytes_fit);
        message += ", live-clocks=[";
        message += identities(live_clocks);
        message += "], frozen-clocks=[";
        message += identities(shape.logical_clock_identities);
        message += "])";
        throw std::logic_error(std::move(message));
      }
    }

    if (authority.staging_capacity_receiver != nullptr) {
      auto staging = runtime::program::amr_program_accepted_state_staging_capacity(shape, accepted);
      // The host-resident forward ceiling is intentionally derived from the configured hierarchy,
      // not from an arbitrary multiple of the accepted image.  A level can be represented both
      // by one full-domain patch and by its finite unit-patch decomposition.  For every block we
      // charge their ghost-grown cell payloads with the declared component count; the flux and
      // interface terms are the independently authenticated Program budgets calculated above.
      // Candidate preparation still measures its concrete B bundle and rejects it if this
      // configured envelope is insufficient, so this formula is an authority rather than a
      // hidden grow-on-demand reserve.
      using configured_field_type = typename Impl::field_type;
      using configured_fab_type = typename configured_field_type::fab_type;
      using configured_engine_type =
          ::pops::numerics::time::amr::PreparedMultiBlockAmrSubcyclingEngine<
              Dim, std::vector<Real>, typename AmrSystem<Dim>::memory_space>;
      using configured_ledger_type = typename configured_engine_type::ledger_type;
      using configured_transition_type = ::pops::numerics::time::amr::PreparedAmrSubcycleTransition<
          Dim, typename AmrSystem<Dim>::memory_space>;
      using configured_face_fragment_type =
          ::pops::amr::reflux::FaceFluxFragment<Dim, runtime::program::AmrProgramFacePayload>;
      using configured_interface_fragment_type =
          ::pops::amr::InterfaceFluxFragment<runtime::program::AmrProgramFacePayload>;
      using configured_interface_ledger_type =
          ::pops::amr::TransactionalInterfaceFluxLedger<runtime::program::AmrProgramFacePayload>;
      runtime::program::PreparedAmrForwardStorageCounts configured_counts;
      std::size_t configured_field_values = 0;
      std::vector<std::uint64_t> configured_field_values_by_level;
      configured_field_values_by_level.reserve(configured_levels);
      staging.configured_level_cell_bounds.reserve(configured_levels);
      staging.configured_patch_bounds.reserve(configured_levels);
      staging.configured_parent_child_pair_bounds.reserve(configured_levels - 1U);
      staging.configured_route_bounds.reserve(configured_levels - 1U);
      staging.configured_event_bounds.reserve(configured_levels - 1U);
      Box<Dim> storage_domain = configuration.index_domain();
      for (std::size_t level = 0; level < configured_levels; ++level) {
        const std::size_t cells = checked_cells(storage_domain);
        staging.configured_level_cell_bounds.push_back(static_cast<std::uint64_t>(cells));
        // P_l = C_l: a future layout may split every configured cell into its own patch.  This
        // is the only topology-independent finite patch bound; the full-domain patch is merely
        // one member of that same decomposition, never a second resident layout.
        const std::size_t patches = cells;
        staging.configured_patch_bounds.push_back(static_cast<std::uint64_t>(patches));
        std::size_t level_field_values = 0;
        for (const auto& block : block_identities) {
          std::size_t full_grown_cells = 1;
          std::size_t unit_grown_cells = 1;
          for (int axis = 0; axis < Dim; ++axis) {
            const auto ghost = static_cast<std::size_t>(block.ghosts[axis]);
            const auto full_extent = static_cast<std::size_t>(storage_domain.length(axis));
            full_grown_cells = checked_size_product(
                full_grown_cells,
                checked_size_sum(
                    full_extent,
                    checked_size_product(2, ghost, "AMR subcycling ghost extent exceeds size_t"),
                    "AMR subcycling ghost extent exceeds size_t"),
                "AMR configured subcycling full patch exceeds size_t");
            unit_grown_cells = checked_size_product(
                unit_grown_cells,
                checked_size_sum(std::size_t{1},
                                 checked_size_product(
                                     2, ghost, "AMR subcycling unit ghost extent exceeds size_t"),
                                 "AMR subcycling unit ghost extent exceeds size_t"),
                "AMR configured subcycling unit patch exceeds size_t");
          }
          const std::size_t unit_patch_cells = checked_size_product(
              cells, unit_grown_cells, "AMR configured subcycling unit patches exceed size_t");
          (void)full_grown_cells;
          configured_field_values = checked_size_sum(
              configured_field_values,
              checked_size_product(unit_patch_cells, static_cast<std::size_t>(block.ncomp),
                                   "AMR configured subcycling field values exceed size_t"),
              "AMR configured subcycling field values exceed size_t");
          level_field_values = checked_size_sum(
              level_field_values,
              checked_size_product(unit_patch_cells, static_cast<std::size_t>(block.ncomp),
                                   "AMR configured coupling field values exceed size_t"),
              "AMR configured coupling field values exceed size_t");
        }
        configured_field_values_by_level.push_back(static_cast<std::uint64_t>(level_field_values));
        if (level + 1 != configured_levels)
          storage_domain = amr::hierarchy::refine_box(
              storage_domain, refinement_ratio(configuration.transition_ratios[level]));
      }
      std::size_t route_executions = 1;
      for (std::size_t parent = 0; parent + 1U < configured_levels; ++parent) {
        const std::size_t parent_patches =
            static_cast<std::size_t>(staging.configured_patch_bounds[parent]);
        const std::size_t child_patches =
            static_cast<std::size_t>(staging.configured_patch_bounds[parent + 1U]);
        // Q_l bounds each coarse/fine layout-pair and therefore the copied interface identities,
        // transfer footprints and average-down route table.
        const std::size_t pairs = checked_size_product(
            parent_patches, child_patches,
            "AMR configured subcycling parent-child patch pairs exceed size_t");
        staging.configured_parent_child_pair_bounds.push_back(static_cast<std::uint64_t>(pairs));
        const auto temporal = relations[parent].temporal_ratio();
        const std::size_t substeps =
            static_cast<std::size_t>(temporal.numerator / temporal.denominator +
                                     (temporal.numerator % temporal.denominator == 0 ? 0 : 1));
        route_executions =
            checked_size_product(route_executions, substeps,
                                 "AMR configured subcycling route invocations exceed size_t");
        // R_l is the complete directed face-route/ledger invocation bound: executions, all
        // program RHS bases, all axis/sides and every parent-child patch pair.
        std::size_t routes =
            checked_size_product(route_executions, rhs_basis,
                                 "AMR configured subcycling route basis invocations exceed size_t");
        routes = checked_size_product(routes, static_cast<std::size_t>(2 * Dim),
                                      "AMR configured subcycling face routes exceed size_t");
        routes = checked_size_product(routes, pairs,
                                      "AMR configured subcycling patch routes exceed size_t");
        staging.configured_route_bounds.push_back(static_cast<std::uint64_t>(routes));
        // E_l is the exact two-phase (reflux/average-down) event pool per program block.
        const std::size_t events = checked_size_product(
            checked_size_product(block_identities.size(), std::size_t{2},
                                 "AMR configured subcycling event phases exceed size_t"),
            std::size_t{1}, "AMR configured subcycling event bound exceeds size_t");
        staging.configured_event_bounds.push_back(static_cast<std::uint64_t>(events));
      }
      if (authority.preparation_image == nullptr || !*authority.preparation_image)
        throw std::logic_error(
            "AMR configured forward storage has no detached Program preparation image");
      const auto tensor_storage =
          runtime::program::staged_amr_hierarchy_tensor_storage_receipt<Dim>(
              *authority.preparation_image, staging.configured_level_cell_bounds,
              staging.configured_patch_bounds, staging.configured_parent_child_pair_bounds,
              static_cast<std::uint64_t>(lane.size()));
      if ((!tensor_storage.active && !tensor_storage.is_canonical_inactive()) ||
          (tensor_storage.active && (tensor_storage.maximum_bytes == 0 ||
                                     tensor_storage.configured_request_contract.empty() ||
                                     tensor_storage.configured_limit_contract.empty())))
        throw std::logic_error("AMR configured forward tensor storage receipt is not canonical");
      staging.configured_tensor_provider_bytes = tensor_storage.maximum_bytes;
      staging.configured_tensor_provider_request_contract =
          tensor_storage.configured_request_contract;
      staging.configured_tensor_provider_limit_contract = tensor_storage.configured_limit_contract;
      configured_counts.level_cell_bounds = staging.configured_level_cell_bounds;
      configured_counts.patch_bounds = staging.configured_patch_bounds;
      configured_counts.parent_child_pair_bounds = staging.configured_parent_child_pair_bounds;
      configured_counts.route_bounds = staging.configured_route_bounds;
      configured_counts.event_bounds = staging.configured_event_bounds;
      configured_counts.rank_bound = static_cast<std::uint64_t>(lane.size());
      configured_counts.tensor_provider_bytes = staging.configured_tensor_provider_bytes;
      // The thirteen retained MultiFab families are named in the checkpoint type.  Keep the
      // [block][level] value bound on every named family rather than folding them into a hidden
      // field multiplier: a new carrier must extend this list and its byte receipt explicitly.
      for (std::size_t family = 0;
           family != runtime::program::PreparedAmrForwardStorageCounts::multifab_family_count;
           ++family)
        configured_counts.multifab_value_counts[family] =
            static_cast<std::uint64_t>(configured_field_values);
      std::size_t route_count = 0;
      std::size_t event_count = 0;
      std::size_t pair_count = 0;
      for (const auto value : configured_counts.route_bounds)
        route_count = checked_size_sum(route_count, static_cast<std::size_t>(value),
                                       "AMR configured route count exceeds size_t");
      for (const auto value : configured_counts.event_bounds)
        event_count = checked_size_sum(event_count, static_cast<std::size_t>(value),
                                       "AMR configured event count exceeds size_t");
      for (const auto value : configured_counts.parent_child_pair_bounds)
        pair_count = checked_size_sum(pair_count, static_cast<std::size_t>(value),
                                      "AMR configured pair count exceeds size_t");
      configured_counts.face_payload_values =
          std::max<std::uint64_t>(static_cast<std::uint64_t>(shape.face_payload_terms),
                                  static_cast<std::uint64_t>(route_count));
      configured_counts.interface_payload_values =
          std::max<std::uint64_t>(static_cast<std::uint64_t>(shape.interface_payload_terms),
                                  static_cast<std::uint64_t>(route_count));

      const auto checked_u64 = [](std::size_t value, const char* what) -> std::uint64_t {
        if (value > std::numeric_limits<std::uint64_t>::max())
          throw std::overflow_error(what);
        return static_cast<std::uint64_t>(value);
      };
      const auto add_bytes = [](std::uint64_t& total, std::uint64_t value, const char* what) {
        if (value > std::numeric_limits<std::uint64_t>::max() - total)
          throw std::overflow_error(what);
        total += value;
      };
      const auto multiply = [](std::uint64_t left, std::uint64_t right, const char* what) {
        if (left != 0 && right > std::numeric_limits<std::uint64_t>::max() / left)
          throw std::overflow_error(what);
        return left * right;
      };
      // One named field family is a complete [block][level] matrix.  Count the MultiFab object
      // and its reporter metadata once for every matrix entry, not once per level globally.  The
      // two vector layers are retained by the matrix owner and are therefore part of every named
      // family too; `resident_storage_bytes()` reports neither enclosing vector allocation.
      std::uint64_t one_field = 0;
      const auto block_count_for_fields = checked_u64(
          block_identities.size(), "AMR configured field matrix block count exceeds uint64");
      add_bytes(one_field, sizeof(std::vector<std::vector<configured_field_type>>),
                "AMR configured field matrix outer carrier overflows uint64");
      add_bytes(one_field,
                multiply(block_count_for_fields, sizeof(std::vector<configured_field_type>),
                         "AMR configured field matrix row carriers overflow uint64"),
                "AMR configured field matrix row carriers overflow uint64");
      for (const auto patches : configured_counts.patch_bounds) {
        const auto patch_count = checked_u64(static_cast<std::size_t>(patches),
                                             "AMR configured patch count exceeds uint64");
        const auto metadata_per_patch =
            static_cast<std::uint64_t>(2U * sizeof(Box<Dim>) + sizeof(Index<Dim>) +
                                       2U * sizeof(std::size_t) + sizeof(configured_fab_type));
        if (patch_count > std::numeric_limits<std::uint64_t>::max() / metadata_per_patch)
          throw std::overflow_error("AMR configured MultiFab metadata overflows uint64");
        const auto entries = block_count_for_fields;
        add_bytes(one_field,
                  multiply(entries, sizeof(configured_field_type),
                           "AMR configured field object matrix overflows uint64"),
                  "AMR configured field object matrix overflows uint64");
        add_bytes(one_field,
                  multiply(entries, patch_count * metadata_per_patch,
                           "AMR configured MultiFab metadata matrix overflows uint64"),
                  "AMR configured MultiFab metadata overflows uint64");
      }
      const auto values = configured_counts.multifab_value_counts.front();
      if (values > std::numeric_limits<std::uint64_t>::max() / sizeof(Real))
        throw std::overflow_error("AMR configured MultiFab payload overflows uint64");
      add_bytes(one_field, values * sizeof(Real),
                "AMR configured MultiFab payload overflows uint64");

      // C(n) is the exact configured coupling image at hierarchy depth n.  The scalar sequence
      // is authenticated with the checkpoint envelope, while the concrete accepted/forward/
      // inverse images remain independently owned by the prepared hierarchy and its regrid
      // transaction stack.  The prepared binding owns the one shared footprint implementation so
      // a newly retained vector, field image or raw host arena cannot hide behind a multiplier.
      if (authority.prepared_coupling_binding != nullptr) {
        const auto& binding = *authority.prepared_coupling_binding;
        using configured_shape = typename Impl::multiblock_type::
            PreparedProgramInterfaceInvocationBinding::ConfiguredCouplingLevelShape;
        std::vector<configured_shape> configured_shapes;
        configured_shapes.reserve(configured_levels);
        staging.configured_hierarchy_contract_characters_by_level.reserve(configured_levels);
        for (std::size_t level = 0; level < configured_levels; ++level) {
          const auto hierarchy_contract_characters =
              binding.configured_hierarchy_contract_payload_bytes(
                  static_cast<std::size_t>(
                      configured_spatial_contract_characters_by_level.at(level)),
                  level + 1U);
          staging.configured_hierarchy_contract_characters_by_level.push_back(
              static_cast<std::uint64_t>(hierarchy_contract_characters));
          configured_shapes.push_back(
              {.block_count = block_identities.size(),
               .global_patch_count = staging.configured_patch_bounds.at(level),
               .local_patch_count = staging.configured_patch_bounds.at(level),
               .owner_count = level == 0 && !authority.config->distribute_coarse
                                  ? 0U
                                  : staging.configured_patch_bounds.at(level),
               .field_value_count = configured_field_values_by_level.at(level),
               .hierarchy_contract_characters = hierarchy_contract_characters});
        }
        staging.configured_coupling_workspace_bytes_by_level =
            binding.configured_workspace_storage_bytes_by_level(configured_shapes);
      }

      runtime::program::PreparedAmrForwardStorageBytes configured_bytes;
      add_bytes(configured_bytes.engine, sizeof(configured_engine_type),
                "AMR configured engine object overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine candidate field overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine older field overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine staged field overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine accepted history field overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine accepted history field overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine candidate history field overflows uint64");
      add_bytes(configured_bytes.engine, one_field,
                "AMR configured engine candidate history field overflows uint64");
      add_bytes(configured_bytes.mutable_state, one_field,
                "AMR configured mutable history field overflows uint64");
      add_bytes(configured_bytes.mutable_state, one_field,
                "AMR configured mutable history field overflows uint64");
      add_bytes(configured_bytes.hot_workspace, one_field,
                "AMR configured workspace field overflows uint64");
      if (authority.prepared_coupling_binding != nullptr) {
        if (staging.configured_coupling_workspace_bytes_by_level.size() != configured_levels)
          throw std::logic_error(
              "AMR configured coupling workspace capacity has an incomplete level sequence");
        if (staging.configured_hierarchy_contract_characters_by_level.size() != configured_levels)
          throw std::logic_error(
              "AMR configured hierarchy contract capacity has an incomplete level sequence");
        const auto& coupling_by_level = staging.configured_coupling_workspace_bytes_by_level;
        std::uint64_t coupling_peak = coupling_by_level.back();  // accepted A=C(L)
        // A full accepted hierarchy may start a non-monotone regrid sweep.  The first inverse
        // retains C(L); each parent p creates forward C(p+2), and every later inverse retains
        // C(p+1).  This is the explicit owner fold A + sum(F_i + I_i), not *N arithmetic.
        if (configured_levels > 1) {
          add_bytes(coupling_peak, coupling_by_level.back(),
                    "AMR configured coupling inverse workspace overflows uint64");
          for (std::size_t level = 1; level < configured_levels; ++level)
            add_bytes(coupling_peak, coupling_by_level.at(level),
                      "AMR configured coupling forward workspace overflows uint64");
          for (std::size_t level = 1; level + 1U < configured_levels; ++level)
            add_bytes(coupling_peak, coupling_by_level.at(level),
                      "AMR configured coupling inverse workspace overflows uint64");
        }
        add_bytes(configured_bytes.prepared_coupling, coupling_peak,
                  "AMR configured prepared coupling workspace overflows uint64");
      }
      add_bytes(configured_bytes.hot_workspace, one_field,
                "AMR configured workspace field overflows uint64");
      add_bytes(configured_bytes.hot_workspace, one_field,
                "AMR configured workspace field overflows uint64");
      add_bytes(configured_bytes.hot_workspace, one_field,
                "AMR configured workspace field overflows uint64");
      const auto block_count_u64 =
          checked_u64(block_identities.size(), "AMR configured block count exceeds uint64");
      const auto route_count_u64 =
          checked_u64(route_count, "AMR configured route count exceeds uint64");
      const auto event_count_u64 =
          checked_u64(event_count, "AMR configured event count exceeds uint64");
      const auto pair_count_u64 =
          checked_u64(pair_count, "AMR configured pair count exceeds uint64");
      const auto transition_count_u64 =
          checked_u64(configured_levels - 1U, "AMR configured transition count exceeds uint64");
      // These are the concrete objects retained by the corresponding reporters: two engine
      // ledger matrices and one mutable rollback matrix, plus the plan's transition objects and
      // copied parent/child/interface patch-owner-footprint vectors.
      add_bytes(configured_bytes.engine,
                multiply(multiply(block_count_u64, route_count_u64,
                                  "AMR configured engine ledger count overflows uint64"),
                         sizeof(configured_ledger_type),
                         "AMR configured engine ledger bytes overflow uint64"),
                "AMR configured engine ledger bytes overflow uint64");
      add_bytes(configured_bytes.engine,
                multiply(multiply(block_count_u64, route_count_u64,
                                  "AMR configured candidate ledger count overflows uint64"),
                         sizeof(configured_ledger_type),
                         "AMR configured candidate ledger bytes overflow uint64"),
                "AMR configured candidate ledger bytes overflow uint64");
      add_bytes(configured_bytes.mutable_state,
                multiply(multiply(block_count_u64, route_count_u64,
                                  "AMR configured mutable ledger count overflows uint64"),
                         sizeof(configured_ledger_type),
                         "AMR configured mutable ledger bytes overflow uint64"),
                "AMR configured mutable ledger bytes overflow uint64");
      add_bytes(configured_bytes.engine,
                multiply(transition_count_u64, sizeof(configured_transition_type),
                         "AMR configured transition bytes overflow uint64"),
                "AMR configured transition bytes overflow uint64");
      add_bytes(configured_bytes.engine,
                multiply(pair_count_u64, sizeof(Box<Dim>),
                         "AMR configured interface footprint bytes overflow uint64"),
                "AMR configured interface footprint bytes overflow uint64");
      // A candidate retains four face images (logical accepted, cold slot, staging logical and
      // staging slot) and four matching event images.  These are separate owners observed by
      // forward_candidate_resident_storage_bytes_(), not an arbitrary safety factor.
      const auto face_fragment_count = std::max(
          route_count_u64, checked_u64(shape.face_fragment_counts[0],
                                       "AMR configured face fragment bound exceeds uint64"));
      // The prepared interface ledger exposes its own frozen fragment bound.  Face-route
      // invocations are a different family and must never be substituted for it.
      const auto interface_fragment_count = checked_u64(
          shape.interface_fragment_count, "AMR configured interface fragment bound exceeds uint64");
      const auto face_identity_bytes = checked_u64(
          checked_size_sum(
              checked_size_sum(shape.face_owner_characters, shape.face_state_characters,
                               "AMR configured face identity bytes exceed size_t"),
              shape.face_stage_characters, "AMR configured face identity bytes exceed size_t"),
          "AMR configured face identity bytes exceed uint64");
      const auto interface_identity_bytes = checked_u64(
          checked_size_sum(
              checked_size_product(shape.interface_fragment_count,
                                   shape.interface_identity_characters,
                                   "AMR configured interface identity bytes exceed size_t"),
              checked_size_sum(shape.interface_program_identity_characters,
                               checked_size_product(
                                   shape.interface_fragment_count, shape.interface_stage_characters,
                                   "AMR configured interface stage bytes exceed size_t"),
                               "AMR configured interface identity bytes exceed size_t"),
              "AMR configured interface identity bytes exceed size_t"),
          "AMR configured interface identity bytes exceed uint64");
      const auto add_face_image = [&](const char* fragment_error, const char* payload_error,
                                      const char* identity_error) {
        add_bytes(
            configured_bytes.flux,
            multiply(face_fragment_count, sizeof(configured_face_fragment_type), fragment_error),
            fragment_error);
        add_bytes(configured_bytes.flux,
                  multiply(configured_counts.face_payload_values, sizeof(Real), payload_error),
                  payload_error);
        add_bytes(configured_bytes.flux,
                  multiply(face_fragment_count, face_identity_bytes, identity_error),
                  identity_error);
      };
      add_face_image("AMR configured accepted face fragment bytes overflow uint64",
                     "AMR configured accepted face payload bytes overflow uint64",
                     "AMR configured accepted face identity bytes overflow uint64");
      add_face_image("AMR configured face slot fragment bytes overflow uint64",
                     "AMR configured face slot payload bytes overflow uint64",
                     "AMR configured face slot identity bytes overflow uint64");
      add_face_image("AMR configured staging face fragment bytes overflow uint64",
                     "AMR configured staging face payload bytes overflow uint64",
                     "AMR configured staging face identity bytes overflow uint64");
      add_face_image("AMR configured staging face slot fragment bytes overflow uint64",
                     "AMR configured staging face slot payload bytes overflow uint64",
                     "AMR configured staging face slot identity bytes overflow uint64");
      const auto add_interface_image = [&](const char* fragment_error, const char* payload_error,
                                           const char* identity_error) {
        add_bytes(configured_bytes.flux,
                  multiply(interface_fragment_count, sizeof(configured_interface_fragment_type),
                           fragment_error),
                  fragment_error);
        add_bytes(configured_bytes.flux,
                  multiply(configured_counts.interface_payload_values, sizeof(Real), payload_error),
                  payload_error);
        add_bytes(configured_bytes.flux, interface_identity_bytes, identity_error);
      };
      add_interface_image("AMR configured accepted interface fragment bytes overflow uint64",
                          "AMR configured accepted interface payload bytes overflow uint64",
                          "AMR configured accepted interface identity bytes overflow uint64");
      add_interface_image("AMR configured staging interface fragment bytes overflow uint64",
                          "AMR configured staging interface payload bytes overflow uint64",
                          "AMR configured staging interface identity bytes overflow uint64");
      // PreparedSubcyclingBundle retains an independent transactional interface ledger alongside
      // the accepted/staging checkpoint DTO images above.  Its resident carriers (three dense
      // images, savepoints and authenticated contracts) are configured from the same frozen
      // InterfaceFluxLedgerBudget, but are owned by the bundle and therefore reported separately
      // by PreparedSubcyclingBundle::resident_storage_bytes().  Materialize that exact cold
      // family here instead of approximating it from fragment counts: the ledger's contract
      // carriers intentionally depend on the sealed budget grammar as well as its capacities.
      const auto configured_interface_ledger_resident_bytes = [&]() -> std::uint64_t {
        configured_interface_ledger_type ledger(/*topology_epoch=*/0, interface);
        ledger.prime_snapshot_arenas_at_bind();
        ledger.prime_snapshot_slots_at_bind();
        ledger.prime_hot_carriers_at_bind();
        const auto dynamic_bytes = ledger.resident_storage_bytes();
        if (dynamic_bytes > std::numeric_limits<std::uint64_t>::max() - sizeof(ledger))
          throw std::overflow_error("AMR configured interface ledger bytes overflow uint64");
        return static_cast<std::uint64_t>(sizeof(ledger)) + dynamic_bytes;
      }();
      add_bytes(configured_bytes.flux, configured_interface_ledger_resident_bytes,
                "AMR configured interface ledger bytes overflow uint64");
      const auto add_event_image = [&](const char* event_error, const char* phase_error) {
        add_bytes(configured_bytes.effects,
                  multiply(event_count_u64,
                           sizeof(runtime::program::AmrProgramSynchronizationEvent), event_error),
                  event_error);
        add_bytes(
            configured_bytes.effects,
            multiply(event_count_u64, std::string_view("average_down").size() + 1U, phase_error),
            phase_error);
      };
      add_event_image("AMR configured accepted synchronization event bytes overflow uint64",
                      "AMR configured accepted synchronization phase bytes overflow uint64");
      add_event_image("AMR configured synchronization slot bytes overflow uint64",
                      "AMR configured synchronization slot phase bytes overflow uint64");
      add_event_image("AMR configured staging synchronization event bytes overflow uint64",
                      "AMR configured staging synchronization phase bytes overflow uint64");
      add_event_image("AMR configured staging synchronization slot bytes overflow uint64",
                      "AMR configured staging synchronization slot phase bytes overflow uint64");
      add_bytes(configured_bytes.effects, shape.spatial_contract_characters,
                "AMR configured spatial contract bytes overflow uint64");
      add_bytes(configured_bytes.effects, shape.face_owner_characters,
                "AMR configured face owner bytes overflow uint64");
      add_bytes(configured_bytes.effects, shape.face_state_characters,
                "AMR configured face state bytes overflow uint64");
      add_bytes(configured_bytes.effects, shape.face_stage_characters,
                "AMR configured face stage bytes overflow uint64");
      add_bytes(configured_bytes.effects, shape.interface_identity_characters,
                "AMR configured interface identity bytes overflow uint64");
      add_bytes(configured_bytes.effects, shape.interface_program_identity_characters,
                "AMR configured interface program identity bytes overflow uint64");
      // POPSAND5 has two simultaneously resident B carriers: the serialized candidate buffer
      // and the decoded staging image.  Their bounds are the schema capacity itself; every
      // variable-size member in the decoded image is constrained by that same frozen shape.
      const auto checkpoint_bytes =
          checked_u64(accepted, "AMR configured POPSAND5 staging capacity exceeds uint64");
      add_bytes(configured_bytes.effects, checkpoint_bytes,
                "AMR configured POPSAND5 candidate bytes overflow uint64");
      add_bytes(configured_bytes.effects, checkpoint_bytes,
                "AMR configured POPSAND5 decoded staging bytes overflow uint64");
      add_bytes(
          configured_bytes.effects,
          checked_u64(checked_size_sum(sizeof(runtime::program::AmrProgramAcceptedState<Dim>),
                                       sizeof(runtime::program::AcceptedStateStaging<Dim>),
                                       "AMR configured POPSAND5 staging objects exceed size_t"),
                      "AMR configured POPSAND5 staging objects exceed uint64"),
          "AMR configured POPSAND5 staging objects overflow uint64");
      configured_bytes.tensor = configured_counts.tensor_provider_bytes;
      staging.configured_forward_storage_counts = std::move(configured_counts);
      staging.configured_forward_storage_bytes = configured_bytes;
      staging.configured_live_subcycling_bytes = configured_bytes.live_subcycling();
      // A and B are distinct owner images.  They are deliberately summed as named reporter
      // families, rather than multiplying one opaque total: A is the detached rollback image
      // and B is the candidate assembled below.  POPSAND5's wire buffer is a component of the
      // effects family, not a substitute for either host-resident image.
      const auto configured_a_rollback_bytes = configured_bytes.live_subcycling();
      if (configured_a_rollback_bytes >
          std::numeric_limits<std::uint64_t>::max() - staging.configured_live_subcycling_bytes)
        throw std::overflow_error("AMR configured forward A+B snapshot envelope exceeds uint64");
      staging.configured_forward_snapshot_bytes =
          configured_a_rollback_bytes + staging.configured_live_subcycling_bytes;
      staging.configured_rank_bound = static_cast<std::size_t>(lane.size());
      ExactContractBuilder storage_contract;
      storage_contract.text("pops.amr-program.configured-forward-subcycling-storage.v2")
          .scalar(std::int32_t{Dim})
          .sequence(staging.configured_level_cell_bounds,
                    [](ExactContractBuilder& row, std::uint64_t cells) { row.scalar(cells); })
          .sequence(staging.configured_patch_bounds,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .sequence(staging.configured_parent_child_pair_bounds,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .sequence(staging.configured_route_bounds,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .sequence(staging.configured_event_bounds,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .sequence(staging.configured_hierarchy_contract_characters_by_level,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .sequence(staging.configured_coupling_workspace_bytes_by_level,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .sequence(staging.configured_forward_storage_counts.multifab_value_counts,
                    [](ExactContractBuilder& row, std::uint64_t value) { row.scalar(value); })
          .scalar(staging.configured_forward_storage_counts.face_payload_values)
          .scalar(staging.configured_forward_storage_counts.interface_payload_values)
          .scalar(staging.configured_forward_storage_bytes.engine)
          .scalar(staging.configured_forward_storage_bytes.mutable_state)
          .scalar(staging.configured_forward_storage_bytes.hot_workspace)
          .scalar(staging.configured_forward_storage_bytes.prepared_coupling)
          .scalar(staging.configured_forward_storage_bytes.flux)
          .scalar(staging.configured_forward_storage_bytes.effects)
          .scalar(staging.configured_forward_storage_bytes.tensor)
          .scalar(staging.configured_live_subcycling_bytes)
          .scalar(staging.configured_forward_snapshot_bytes)
          .scalar(static_cast<std::uint64_t>(staging.configured_rank_bound))
          .scalar(staging.configured_tensor_provider_bytes)
          .bytes(staging.configured_tensor_provider_request_contract)
          .bytes(staging.configured_tensor_provider_limit_contract)
          .scalar(static_cast<std::uint64_t>(shape.face_payload_terms))
          .scalar(static_cast<std::uint64_t>(shape.interface_payload_terms))
          .bytes(expression.exact_contract)
          .bytes(interface.exact_contract);
      staging.configured_subcycling_storage_contract = std::move(storage_contract).release();
      *authority.staging_capacity_receiver = std::move(staging);
    }

    ExactContractBuilder exact;
    exact.text("pops.amr-system.checkpoint-program-state-capacity")
        .scalar(std::uint32_t{1})
        .scalar(std::int32_t{Dim})
        .text(installed_hash)
        .bytes(expression.exact_contract)
        .bytes(interface.exact_contract)
        .scalar(static_cast<std::uint64_t>(configured_levels))
        .scalar(static_cast<std::uint64_t>(accepted))
        .scalar(static_cast<std::uint64_t>(source_authority_bytes))
        .sequence(
            metadata.logical_clock_identities,
            [](ExactContractBuilder& row, const std::string& identity) { row.text(identity); })
        .sequence(shape.histories,
                  [](ExactContractBuilder& row,
                     const runtime::program::AmrProgramHistoryDescriptor& history) {
                    row.text(history.name)
                        .scalar(std::int32_t{history.program_owner})
                        .text(history.state_identity)
                        .text(history.space_identity)
                        .text(history.clock_identity)
                        .text(history.interpolation_identity)
                        .scalar(std::int32_t{history.depth})
                        .scalar(std::int32_t{history.components});
                  })
        .text(shape.temporal_provider_identity)
        .scalar(static_cast<std::uint64_t>(shape.temporal_cell_count))
        .scalar(static_cast<std::uint64_t>(shape.spatial_contract_characters))
        .scalar(static_cast<std::uint64_t>(shape.tagging_hysteresis_bytes))
        .scalar(static_cast<std::uint64_t>(shape.face_fragment_counts[0]))
        .scalar(static_cast<std::uint64_t>(shape.face_payload_terms))
        .scalar(static_cast<std::uint64_t>(shape.interface_fragment_count))
        .scalar(static_cast<std::uint64_t>(shape.interface_payload_terms))
        .scalar(static_cast<std::uint64_t>(shape.interface_identity_characters))
        .scalar(static_cast<std::uint64_t>(shape.interface_program_identity_characters));
    // The POPSAND5 capacity contract is intentionally independent of whether this invocation is
    // the first staging pass (which has a receiver) or the bootstrap verification pass (which
    // does not).  The forward-storage envelope is authenticated separately by its own sealed
    // storage contract and is embedded in every forward-candidate receipt; making this wire
    // contract conditional on a transient receiver made the two otherwise identical passes
    // disagree before any Candidate could be prepared.
    candidate.emplace(accepted, source_authority_bytes);
    candidate_contract = std::move(exact).release();
  } catch (...) {
    local_error = std::current_exception();
  }
  if (all_reduce_max(local_error ? 1L : 0L, lane.communicator()) != 0) {
    if (lane.size() == 1 && local_error)
      std::rethrow_exception(local_error);
    throw std::runtime_error("AMR Program checkpoint capacity preparation failed collectively");
  }
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-program-checkpoint-capacity"),
            std::string_view(candidate_contract)}},
          lane.communicator()))
    throw std::invalid_argument(
        "AMR Program checkpoint capacities differ between prepared-lane ranks");
  if (authority.prepared_contract == nullptr)
    throw std::logic_error("AMR Program checkpoint candidate has no exact-contract receiver");
  authority.prepared_contract->swap(candidate_contract);
  return *candidate;
}

template <int Dim>
std::vector<std::uint8_t> AmrSystem<Dim>::program_accepted_state() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  return program_accepted_state_();
}

template <int Dim>
std::vector<std::uint8_t> AmrSystem<Dim>::program_accepted_state_() const {
  if (p_->program_accepted_bytes.empty() && !p_->program.artifact_backed_ && !p_->tagging_spec)
    return {};
  if (!p_->engine)
    p_->ensure_engine();
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  runtime::program::AmrProgramAcceptedState<Dim> state =
      p_->program_accepted_bytes.empty()
          ? p_->minimal_program_accepted_state()
          : runtime::program::deserialize_amr_program_accepted_state<Dim>(
                p_->program_accepted_bytes, &interface_budget);
  if (p_->program_accepted_bytes.empty() || p_->program_accepted_bytes_runtime_owned)
    p_->requalify_runtime_owned_program_state(state);
  else
    runtime::program::require_live_amr_program_checkpoint(state, *p_->engine);
  p_->require_accepted_state_authority_contracts(state);
  std::vector<std::uint8_t> serialized =
      runtime::program::serialize_amr_program_accepted_state(state);
  if (p_->checkpoint_program_state_capacity_value &&
      serialized.size() > p_->checkpoint_program_state_capacity_value->first)
    throw std::length_error("AMR Program accepted state exceeds its bind-sealed artifact capacity");
  return serialized;
}

template <int Dim>
void AmrSystem<Dim>::copy_program_accepted_state_into(std::vector<std::uint8_t>& state) const {
  state = program_accepted_state();
}

template <int Dim>
void AmrSystem<Dim>::program_publish_prevalidated_accepted_state_(
    const std::vector<std::uint8_t>& state) {
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AMR Program accepted-state publication requires its prepared lane");
  const ExecutionLane& lane = *p_->prepared_hierarchy->lane;
  std::exception_ptr local_error;
  try {
    if (p_->program_accepted_revision == std::numeric_limits<std::uint64_t>::max())
      throw std::overflow_error("AmrSystem Program accepted-state revision overflow");
    p_->require_program_checkpoint_capacity(state.size(), "AMR Program accepted-state publication");
    if (state.size() > p_->program_accepted_bytes.capacity())
      throw std::logic_error(
          "AMR Program accepted-state publication byte capacity was not primed at bind");
  } catch (...) {
    local_error = std::current_exception();
  }
  if (all_reduce_max(local_error ? 1L : 0L, lane) != 0) {
    if (lane.size() == 1 && local_error)
      std::rethrow_exception(local_error);
    throw std::runtime_error("AMR Program accepted-state publication failed collectively");
  }
  const std::string_view bytes(state.empty() ? "" : reinterpret_cast<const char*>(state.data()),
                               state.size());
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("pops.amr-program-checkpoint"), bytes}}, lane))
    throw std::runtime_error("exact AMR Program checkpoint differs between communicator ranks");
  if (state == p_->program_accepted_bytes)
    return;
  p_->program_accepted_bytes.resize(state.size());
  std::copy(state.begin(), state.end(), p_->program_accepted_bytes.begin());
  ++p_->program_accepted_revision;
  p_->program_accepted_bytes_runtime_owned = false;
}

template <int Dim>
void AmrSystem<Dim>::restore_program_accepted_state(const std::vector<std::uint8_t>& state) {
  p_->ensure_engine();
  if (!p_->prepared_hierarchy || !p_->prepared_hierarchy->lane)
    throw std::logic_error("AMR Program accepted-state restore requires its prepared lane");
  const ExecutionLane& lane = *p_->prepared_hierarchy->lane;
  const std::string_view request_view(
      state.empty() ? "" : reinterpret_cast<const char*>(state.data()), state.size());
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("pops.amr-program-checkpoint-request"), request_view}}, lane))
    throw std::runtime_error(
        "exact AMR Program accepted-state restore request differs between communicator ranks");
  std::optional<runtime::program::AmrProgramAcceptedState<Dim>> decoded;
  std::vector<std::uint8_t> candidate;
  std::exception_ptr local_error;
  try {
    if (p_->program_accepted_revision == std::numeric_limits<std::uint64_t>::max())
      throw std::overflow_error("AmrSystem Program accepted-state revision overflow");
    p_->require_program_checkpoint_capacity(state.size(), "AMR Program accepted-state restore");
    const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
    decoded.emplace(
        runtime::program::deserialize_amr_program_accepted_state<Dim>(state, &interface_budget));
    std::vector<std::uint8_t> canonical_tagging;
    if (p_->tagging_spec)
      canonical_tagging = p_->tagging_state.encode(p_->tagging_spec->min_cycles,
                                                   p_->tagging_spec->provider_identity);
    if (!decoded->tagging_hysteresis_state.empty() &&
        decoded->tagging_hysteresis_state != canonical_tagging)
      throw std::invalid_argument(
          "AMR Program accepted-state restore tagging hysteresis differs from live authority");
    decoded->tagging_hysteresis_state.swap(canonical_tagging);
    runtime::program::require_live_amr_program_checkpoint(*decoded, *p_->engine);
    p_->require_accepted_state_authority_contracts(*decoded);
    candidate = runtime::program::serialize_amr_program_accepted_state(*decoded);
    p_->require_program_checkpoint_capacity(candidate.size(),
                                            "AMR Program accepted-state restore candidate");
    p_->prime_program_accepted_bytes_cold(candidate);
  } catch (...) {
    local_error = std::current_exception();
  }
  if (all_reduce_max(local_error ? 1L : 0L, lane) != 0) {
    if (lane.size() == 1 && local_error)
      std::rethrow_exception(local_error);
    throw std::runtime_error("AMR Program accepted-state restore failed collectively");
  }
  const std::string_view candidate_view(
      candidate.empty() ? "" : reinterpret_cast<const char*>(candidate.data()), candidate.size());
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("pops.amr-program-checkpoint"), candidate_view}}, lane))
    throw std::runtime_error("exact AMR Program checkpoint differs between communicator ranks");
  p_->program_accepted_bytes.swap(candidate);
  p_->program_accepted_bytes_runtime_owned = false;
  ++p_->program_accepted_revision;
}

template <int Dim>
void AmrSystem<Dim>::restore_checkpoint_accepted_state(const std::vector<std::uint8_t>& state) {
  p_->ensure_engine();
  // restart authority requalification can replace prepared_hierarchy and its graph lane; the
  // multiblock lane remains valid for this complete checkpoint transaction.
  const ExecutionLane& lane = p_->multiblock_hierarchy->lane();
  std::optional<runtime::program::AmrProgramAcceptedState<Dim>> decoded;
  std::optional<runtime::amr::PersistentTaggingState<Dim>> decoded_tagging;
  std::optional<::pops::amr::InterfaceFluxLedgerBudget> interface_budget;
  std::exception_ptr local_error;
  long local_failure = 0;
  try {
    p_->require_program_checkpoint_capacity(state.size(), "AMR checkpoint accepted-state restore");
    interface_budget.emplace(p_->accepted_state_interface_flux_ledger_budget());
    decoded.emplace(
        runtime::program::deserialize_amr_program_accepted_state<Dim>(state, &*interface_budget));
  } catch (...) {
    local_failure = 1;
    local_error = std::current_exception();
  }
  if (all_reduce_max(local_failure, lane.communicator()) != 0) {
    if (local_error)
      std::rethrow_exception(local_error);
    throw std::runtime_error("AMR checkpoint tagging state failed validation on another MPI rank");
  }
  runtime::program::require_collective_amr_program_checkpoint_consensus(*decoded, lane);
  const std::string_view encoded_state(reinterpret_cast<const char*>(state.data()), state.size());
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("pops.amr.checkpoint-accepted-state"), encoded_state}}, lane))
    throw std::invalid_argument(
        "AMR checkpoint accepted-state bytes differ between prepared ranks");

  // Every rank reached the same decoded authority before a hierarchy requalification can enter
  // its collective lane.  Keep all allocation/semantic checks after that collective boundary.
  local_error = nullptr;
  local_failure = 0;
  try {
    if (p_->restart_transaction)
      p_->requalify_restart_program_authority(*decoded);
    runtime::program::require_live_amr_program_checkpoint(*decoded, *p_->engine);
    p_->require_accepted_state_authority_contracts(*decoded);
    if (p_->tagging_spec) {
      decoded_tagging.emplace(runtime::amr::PersistentTaggingState<Dim>::decode(
          decoded->tagging_hysteresis_state, p_->tagging_spec->min_cycles,
          p_->tagging_spec->provider_identity, p_->live_tagging_parent_domains()));
    } else {
      if (!decoded->tagging_hysteresis_state.empty())
        throw std::invalid_argument(
            "AMR checkpoint carries tagging hysteresis without a bound tagging authority");
      decoded_tagging.emplace();
    }
  } catch (...) {
    local_failure = 1;
    local_error = std::current_exception();
  }
  if (all_reduce_max(local_failure, lane.communicator()) != 0) {
    if (lane.size() == 1 && local_error)
      std::rethrow_exception(local_error);
    throw std::runtime_error("AMR checkpoint post-requalification validation failed collectively");
  }
  const long exhausted =
      p_->program_accepted_revision == std::numeric_limits<std::uint64_t>::max() ? 1L : 0L;
  if (all_reduce_max(exhausted, lane.communicator()) != 0)
    throw std::overflow_error("AmrSystem Program accepted-state revision overflow");

  std::vector<std::uint8_t> candidate_bytes;
  std::vector<std::uint8_t> previous_bytes;
  std::optional<runtime::amr::PersistentTaggingState<Dim>> previous_tagging;
  bool previous_runtime_owned = false;
  const std::uint64_t previous_revision = p_->program_accepted_revision;
  std::exception_ptr snapshot_error;
  try {
    // Decoding owns a compact byte vector.  Preserve the facade's complete bind-sealed POPSAND5
    // envelope in both local candidates before either can be exchanged with the accepted image:
    // a rejected restore must retain the old envelope, while a successful restore must leave the
    // next accepted refresh allocation-free.
    candidate_bytes = state;
    p_->prime_program_accepted_bytes_cold(candidate_bytes);
    previous_bytes = p_->program_accepted_bytes;
    p_->prime_program_accepted_bytes_cold(previous_bytes);
    previous_tagging.emplace(p_->tagging_state);
    previous_runtime_owned = p_->program_accepted_bytes_runtime_owned;
  } catch (...) {
    snapshot_error = std::current_exception();
  }
  if (all_reduce_max(snapshot_error ? 1L : 0L, lane.communicator()) != 0) {
    if (lane.size() == 1 && snapshot_error)
      std::rethrow_exception(snapshot_error);
    throw std::runtime_error("AMR checkpoint accepted-state snapshot failed collectively");
  }

  static_assert(std::is_nothrow_swappable_v<std::vector<std::uint8_t>>);
  p_->program_accepted_bytes.swap(candidate_bytes);
  p_->program_accepted_bytes_runtime_owned = false;
  p_->tagging_state = std::move(*decoded_tagging);
  ++p_->program_accepted_revision;
  // The outer restart transaction has already requalified and published its live hierarchy before
  // this accepted image becomes visible.  Now that both the native history rings and facade bytes
  // are present, force the Program context to import their complete authenticated provenance.  A
  // failure deliberately escapes to the outer transaction, whose AcceptedSnapshot restores the
  // hierarchy, carriers, bytes, graph and context together.  Its *inner rollback* still performs
  // no early resync while those authorities are in flight.
  std::exception_ptr resync_error;
  try {
    p_->program.resync_after_restart("AmrSystem::restore_checkpoint_accepted_state");
  } catch (...) {
    resync_error = std::current_exception();
  }
  if (all_reduce_max(resync_error ? 1L : 0L, lane.communicator()) == 0) {
    // resync_after_restart may have rebuilt the Program-owned AMR workspace.  The outer step
    // carrier is deliberately not a restart participant, so replace it now while restore remains
    // cold; otherwise its next capture compares the old resident shape with the new live one
    // from inside Candidate and correctly refuses an allocation-bearing repair.
    std::unique_ptr<typename Impl::StepTransactionCarrier> replacement;
    try {
      replacement = p_->prepare_step_transaction_image_after_checkpoint_restore();
    } catch (...) {
      resync_error = std::current_exception();
    }
    if (all_reduce_max(resync_error ? 1L : 0L, lane.communicator()) == 0) {
      // Every rank prepared a complete detached image.  Publication is an exchange-only step
      // after this consensus; a local preparation failure therefore cannot leave any peer with a
      // rollback carrier for the rejected checkpoint authority.
      p_->publish_prepared_step_transaction_image_after_checkpoint_restore(*replacement);
      return;
    }
  }

  if (p_->restart_transaction) {
    if (lane.size() == 1 && resync_error)
      std::rethrow_exception(resync_error);
    throw std::runtime_error(
        "AMR checkpoint accepted-state restart resynchronization failed collectively");
  }

  p_->program_accepted_bytes.swap(previous_bytes);
  p_->program_accepted_bytes_runtime_owned = previous_runtime_owned;
  p_->tagging_state = std::move(*previous_tagging);
  p_->program_accepted_revision = previous_revision;
  std::exception_ptr rollback_resync_error;
  try {
    p_->program.resync_after_restart("AmrSystem::restore_checkpoint_accepted_state rollback");
  } catch (...) {
    rollback_resync_error = std::current_exception();
  }
  if (all_reduce_max(rollback_resync_error ? 1L : 0L, lane.communicator()) != 0) {
    const auto describe = [](const std::exception_ptr& error) {
      if (!error)
        return std::string("failure reported by another prepared-lane rank");
      try {
        std::rethrow_exception(error);
      } catch (const std::exception& exception) {
        return std::string(exception.what());
      } catch (...) {
        return std::string("non-standard exception");
      }
    };
    throw std::runtime_error("AMR checkpoint accepted-state resynchronization failed: original: " +
                             describe(resync_error) +
                             "; rollback: " + describe(rollback_resync_error));
  }
  if (lane.size() == 1 && resync_error)
    std::rethrow_exception(resync_error);
  throw std::runtime_error("AMR checkpoint accepted-state resynchronization failed collectively");
}

template <int Dim>
void AmrSystem<Dim>::materialize_program_restart_histories(const std::vector<std::uint8_t>& state,
                                                           const std::vector<std::string>& names,
                                                           const std::vector<int>& depths,
                                                           const std::vector<int>& ncomps) {
  p_->ensure_engine();
  if (!p_->restart_transaction)
    throw std::logic_error("AMR Program restart histories require one active restart transaction");
  if (names.size() != depths.size() || names.size() != ncomps.size())
    throw std::invalid_argument(
        "AMR Program restart history names, depths and component counts must align");

  // This protocol invokes restart authority requalification before its final consensus, so it
  // must retain the stable multiblock lane rather than a replaceable graph-lane reference.
  const ExecutionLane& lane = p_->multiblock_hierarchy->lane();
  std::exception_ptr decode_error;
  std::optional<runtime::program::AmrProgramAcceptedState<Dim>> decoded_preflight;
  try {
    const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
    decoded_preflight.emplace(
        runtime::program::deserialize_amr_program_accepted_state<Dim>(state, &interface_budget));
  } catch (...) {
    decode_error = std::current_exception();
  }
  if (all_reduce_max(decode_error ? 1L : 0L, lane.communicator()) != 0) {
    if (lane.size() == 1 && decode_error)
      std::rethrow_exception(decode_error);
    throw std::runtime_error("AMR Program restart history decode failed collectively");
  }
  runtime::program::require_collective_amr_program_checkpoint_consensus(*decoded_preflight, lane);
  const std::string_view encoded_state(reinterpret_cast<const char*>(state.data()), state.size());
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("pops.amr.restart-history-state"), encoded_state}}, lane))
    throw std::invalid_argument("AMR Program restart history bytes differ between prepared ranks");

  runtime::program::HistoryManager<Dim> candidate;
  std::string contract;
  std::exception_ptr preparation_error;
  try {
    const auto& accepted = *decoded_preflight;
    p_->requalify_restart_program_authority(accepted);
    runtime::program::require_live_amr_program_checkpoint(accepted, *p_->engine);
    p_->require_accepted_state_authority_contracts(accepted);
    if (accepted.histories.size() != names.size())
      throw std::invalid_argument(
          "AMR Program restart history registry differs from its accepted checkpoint");
    const auto& hierarchy = p_->engine->hierarchy();
    ExactContractBuilder exact;
    exact.text("pops.amr-system.restart-history-materialization")
        .scalar(std::uint32_t{1})
        .scalar(std::int32_t{Dim})
        .bytes(p_->engine->spatial_contract())
        .scalar(static_cast<std::uint64_t>(accepted.histories.size()));
    for (std::size_t index = 0; index < names.size(); ++index) {
      const auto& descriptor = accepted.histories[index];
      if (descriptor.name != names[index] || descriptor.depth != depths[index] ||
          descriptor.components != ncomps[index])
        throw std::invalid_argument(
            "AMR Program restart history arguments differ from the accepted descriptor");
      if (index != 0 && names[index - 1] >= names[index])
        throw std::invalid_argument("AMR Program restart history names must be uniquely ordered");
      if (descriptor.program_owner < 0 ||
          static_cast<std::size_t>(descriptor.program_owner) >= p_->program.block_map_.size())
        throw std::invalid_argument("AMR Program restart history has an invalid program owner");
      const int runtime_owner =
          p_->program.block_map_[static_cast<std::size_t>(descriptor.program_owner)];
      if (runtime_owner < 0 || static_cast<std::size_t>(runtime_owner) >= p_->blocks.size())
        throw std::logic_error("AMR Program restart history maps to an invalid runtime block");
      exact.text(descriptor.name)
          .scalar(std::int32_t{descriptor.program_owner})
          .text(descriptor.state_identity)
          .text(descriptor.space_identity)
          .text(descriptor.clock_identity)
          .text(descriptor.interpolation_identity)
          .scalar(std::int32_t{descriptor.depth})
          .scalar(std::int32_t{descriptor.components});
      for (std::size_t level = 0; level < hierarchy.num_levels(); ++level) {
        const std::string key = exact_amr_history_key(descriptor.name, static_cast<int>(level));
        const MultiFab<Dim>& prototype =
            p_->block_state(static_cast<std::size_t>(runtime_owner), level);
        std::vector<MultiFab<Dim>> ring;
        ring.reserve(static_cast<std::size_t>(descriptor.depth));
        for (int slot = 0; slot < descriptor.depth; ++slot) {
          MultiFab<Dim> field(prototype.layout(), prototype.distribution(), prototype.local_rank(),
                              descriptor.components, prototype.ghosts());
          field.set_val(Real(0));
          ring.push_back(std::move(field));
        }
        candidate.histories.emplace(key, std::move(ring));
        candidate.depth.emplace(key, descriptor.depth);
        candidate.initialized.emplace(key, false);
        candidate.fill_count.emplace(key, 0);
        candidate.store_pending.emplace(key, false);
        candidate.owner.emplace(key, runtime_owner);
        candidate.state_identity.emplace(key, descriptor.state_identity);
        candidate.space_identity.emplace(key, descriptor.space_identity);
        candidate.clock_identity.emplace(key, descriptor.clock_identity);
        candidate.interpolation_identity.emplace(key, descriptor.interpolation_identity);
        candidate.slot_dt.emplace(
            key, std::vector<Real>(static_cast<std::size_t>(descriptor.depth), Real(0)));
      }
    }
    contract = std::move(exact).release();
  } catch (...) {
    preparation_error = std::current_exception();
  }
  if (all_reduce_max(preparation_error ? 1L : 0L, lane.communicator()) != 0) {
    if (lane.size() == 1 && preparation_error)
      std::rethrow_exception(preparation_error);
    throw std::runtime_error(
        "AMR Program restart history materialization failed on at least one MPI rank");
  }
  if (!all_ranks_agree_exact_ordered_byte_pairs(
          {{std::string_view("amr-restart-histories"), std::string_view(contract)}},
          lane.communicator()))
    throw std::invalid_argument("AMR Program restart history contracts differ between MPI ranks");
  p_->program.hist_ = std::move(candidate);
}

template <int Dim>
std::uint64_t AmrSystem<Dim>::program_accepted_state_revision() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  return program_accepted_state_revision_();
}

template <int Dim>
std::uint64_t AmrSystem<Dim>::program_accepted_state_revision_() const noexcept {
  return p_->program_accepted_revision;
}

template <int Dim>
void AmrSystem<Dim>::program_copy_tagging_hysteresis_state_into_(
    std::vector<std::uint8_t>& destination) const {
  if (!p_->tagging_spec) {
    p_->tagging_state.encode_into(destination, 0, {});
    return;
  }
  p_->tagging_state.encode_into(destination, p_->tagging_spec->min_cycles,
                                p_->tagging_spec->provider_identity);
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::program_accepted_state_manifest() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  const auto bytes = program_accepted_state();
  if (bytes.empty())
    return rows;
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  const auto state =
      runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
  rows.reserve(state.history_slots.size());
  for (const auto& provenance : state.history_slots) {
    const auto history =
        std::find_if(state.histories.begin(), state.histories.end(),
                     [&](const auto& candidate) { return candidate.name == provenance.name; });
    if (history == state.histories.end())
      throw std::logic_error("AMR Program accepted manifest lost its history descriptor");
    rows.push_back({history->name, "program.block." + std::to_string(history->program_owner),
                    history->state_identity, history->space_identity, history->clock_identity,
                    history->interpolation_identity, std::to_string(history->depth),
                    std::to_string(state.level_clocks.size()), std::to_string(provenance.level),
                    std::to_string(provenance.slot),
                    std::to_string(std::bit_cast<std::uint64_t>(provenance.outgoing_dt)),
                    provenance.initialized ? "1" : "0", std::to_string(provenance.fill_count)});
  }
  return rows;
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::program_clock_manifest() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  const auto bytes = program_accepted_state();
  if (bytes.empty())
    return rows;
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  const auto state =
      runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
  rows.reserve(state.level_clocks.size() + state.logical_clock_ticks.size());
  for (const auto& clock : state.level_clocks)
    rows.push_back({"level", std::to_string(clock.level), std::to_string(clock.macro_step),
                    std::to_string(clock.phase.numerator), std::to_string(clock.phase.denominator),
                    std::to_string(clock.physical_time)});
  for (const auto& [identity, tick] : state.logical_clock_ticks)
    rows.push_back({"logical", identity, std::to_string(tick)});
  return rows;
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::program_temporal_partition_manifest() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  const auto bytes = program_accepted_state();
  if (bytes.empty())
    return rows;
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  const auto state =
      runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
  const auto& temporal = state.temporal_partition;
  rows.push_back(
      {"summary",
       temporal.kind == runtime::program::TemporalPartitionKind::Global ? "global" : "cell_local",
       temporal.provider_identity, std::to_string(temporal.topology_epoch),
       std::to_string(temporal.synchronization_tick), std::to_string(temporal.tick_denominator),
       std::to_string(temporal.cells.size())});
  std::map<int, std::size_t> rungs;
  for (const auto& cell : temporal.cells)
    ++rungs[cell.rung];
  for (const auto& [rung, count] : rungs)
    rows.push_back({"rung", std::to_string(rung), std::to_string(count)});
  return rows;
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::program_flux_ledger_manifest() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  const auto bytes = program_accepted_state();
  if (bytes.empty())
    return rows;
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  const auto state =
      runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
  for (int axis = 0; axis < Dim; ++axis)
    for (const auto& fragment : state.accepted_face_flux[static_cast<std::size_t>(axis)]) {
      const auto& key = fragment.key;
      const auto& measure = fragment.measure;
      const int level = key.role == ::pops::amr::reflux::FaceLedgerRole::Coarse ? key.levels.coarse
                                                                                : key.levels.fine;
      const std::string orientation =
          std::string(1, static_cast<char>('x' + axis)) +
          (key.role == ::pops::amr::reflux::FaceLedgerRole::Coarse ? "_coarse" : "_fine");
      rows.push_back(
          {key.owner, key.state, key.stage, "numerical_flux", std::to_string(level),
           std::to_string(key.clock.macro_step), std::to_string(key.clock.phase.numerator),
           std::to_string(key.clock.phase.denominator),
           std::to_string(measure.stage_weight.numerator),
           std::to_string(measure.stage_weight.denominator), orientation,
           std::to_string(measure.face_measure), std::to_string(measure.substep_duration)});
    }
  return rows;
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::program_interface_flux_ledger_manifest()
    const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  const auto bytes = program_accepted_state();
  if (bytes.empty())
    return rows;
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  const auto state =
      runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
  for (const auto& fragment : state.accepted_interface_flux) {
    const auto& key = fragment.key;
    const auto& measure = fragment.measure;
    rows.push_back({key.interface_identity,
                    std::to_string(key.topology_epoch),
                    std::to_string(key.coarse_level),
                    std::to_string(key.fine_level),
                    std::to_string(key.clock.level),
                    std::to_string(key.clock.macro_step),
                    std::to_string(key.clock.phase.numerator),
                    std::to_string(key.clock.phase.denominator),
                    std::to_string(key.clock.physical_time),
                    key.stage_identity,
                    std::to_string(key.interval.begin.level),
                    std::to_string(key.interval.begin.macro_step),
                    std::to_string(key.interval.begin.phase.numerator),
                    std::to_string(key.interval.begin.phase.denominator),
                    std::to_string(key.interval.begin.physical_time),
                    std::to_string(key.interval.end.level),
                    std::to_string(key.interval.end.macro_step),
                    std::to_string(key.interval.end.phase.numerator),
                    std::to_string(key.interval.end.phase.denominator),
                    std::to_string(key.interval.end.physical_time),
                    key.orientation == ::pops::amr::InterfaceFluxOrientation::CoarseOutward
                        ? "coarse_outward"
                        : "fine_outward",
                    std::to_string(key.left_block),
                    std::to_string(key.right_block),
                    std::to_string(measure.stage_weight.numerator),
                    std::to_string(measure.stage_weight.denominator),
                    std::to_string(measure.face_measure),
                    std::to_string(measure.substep_duration),
                    measure.stage_weight_resolved ? "resolved" : "unresolved",
                    key.graph_identity,
                    key.rate_identity,
                    key.application_identity});
  }
  return rows;
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::program_sync_manifest() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  const auto bytes = program_accepted_state();
  if (bytes.empty())
    return rows;
  const auto interface_budget = p_->accepted_state_interface_flux_ledger_budget();
  const auto state =
      runtime::program::deserialize_amr_program_accepted_state<Dim>(bytes, &interface_budget);
  rows.reserve(state.synchronization_events.size());
  for (const auto& event : state.synchronization_events)
    rows.push_back({std::to_string(event.parent_level), std::to_string(event.child_level),
                    std::to_string(event.runtime_block), event.phase,
                    std::to_string(event.clock.macro_step),
                    std::to_string(event.clock.phase.numerator),
                    std::to_string(event.clock.phase.denominator)});
  return rows;
}

template <int Dim>
std::vector<::pops::amr::ParentChildClockRelation>
AmrSystem<Dim>::prepared_program_temporal_relations() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  const auto relations = program_prepared_temporal_relations_();
  return {relations.begin(), relations.end()};
}

template <int Dim>
std::span<const ::pops::amr::ParentChildClockRelation>
AmrSystem<Dim>::program_prepared_temporal_relations_() const {
  const auto& witness = p_->require_prepared_hot_path_witness();
  const auto live_levels = p_->engine->hierarchy().num_levels();
  if (live_levels == 0 || p_->temporal_relations.size() + 1 < live_levels)
    throw std::runtime_error(
        "AMR Program temporal hierarchy provider lacks one relation per live transition");
  for (std::size_t transition = 0; transition < p_->temporal_relations.size(); ++transition) {
    const auto& relation = p_->temporal_relations[transition];
    const auto ratio = relation.temporal_ratio();
    if (relation.parent_level() != static_cast<int>(transition) ||
        relation.child_level() != static_cast<int>(transition + 1) || ratio.numerator <= 0 ||
        ratio.denominator <= 0)
      throw std::runtime_error(
          "AMR Program temporal hierarchy provider has a non-canonical level/ratio chain");
  }
  const auto live_transitions = static_cast<std::size_t>(live_levels - 1);
  if (live_transitions > p_->temporal_relations.size() ||
      witness.materialization_generation != p_->engine->materialization_generation())
    throw std::logic_error("AMR Program temporal witness drifted after preparation");
  return {p_->temporal_relations.data(), live_transitions};
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::checkpoint_temporal_relations() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  rows.reserve(p_->temporal_relations.size());
  for (const auto& relation : p_->temporal_relations) {
    const auto ratio = relation.temporal_ratio();
    rows.push_back({std::to_string(relation.parent_level()), std::to_string(relation.child_level()),
                    std::to_string(ratio.numerator), std::to_string(ratio.denominator),
                    relation.remainder_policy() == ::pops::amr::RemainderPolicy::IntegralOnly
                        ? "integral_only"
                        : "explicit_final_substep"});
  }
  return rows;
}

template <int Dim>
std::vector<std::vector<std::string>> AmrSystem<Dim>::checkpoint_transfer_routes() const {
  const auto accepted_read = p_->acquire_accepted_read_lease();
  (void)accepted_read;
  std::vector<std::vector<std::string>> rows;
  rows.reserve(p_->bootstrap_subject_routes.size());
  for (const auto& [key, route_identity] : p_->bootstrap_subject_routes) {
    const auto found = p_->bootstrap_transfer_routes.find(route_identity);
    if (found == p_->bootstrap_transfer_routes.end())
      throw std::logic_error("AMR bootstrap transfer manifest lost a registered provider");
    const typename Impl::BootstrapTransferRoute& route = found->second;
    std::string ghosts;
    std::string ratio;
    for (int axis = 0; axis < Dim; ++axis) {
      if (axis != 0) {
        ghosts.push_back(',');
        ratio.push_back(',');
      }
      ghosts += std::to_string(route.ghost_depth[axis]);
      ratio += std::to_string(route.refinement_ratio[axis]);
    }
    rows.push_back({key.first, key.second, route.identity, route.provider_identity, route.kernel,
                    route.space, route.centering, route.representation, route.storage,
                    route.operation, std::to_string(route.order), std::move(ghosts),
                    std::to_string(Dim), std::move(ratio)});
  }
  return rows;
}

